const save=()=>localStorage.setItem('orbit_demo_v2',JSON.stringify(state));const course=id=>state.courses.find(c=>c.id===id)||{name:'Course',code:'Course',color:'#9aa'};const dateLabel=d=>{let dt=new Date(d+'T12:00:00');return {day:dt.getDate(),mon:dt.toLocaleString('en-US',{month:'short'}),full:dt.toLocaleString('en-US',{month:'short',day:'numeric'})}};const todayISO=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};let today=todayISO();selectedScheduleDate=today;
function toast(msg){let el=document.createElement('div');el.className='toast';el.innerHTML='<strong>Orbit</strong> &nbsp;'+msg;document.getElementById('toast-region').appendChild(el);setTimeout(()=>el.remove(),3000)}
function go(v){if(v==='dashboard'&&!state.onboarded){view='onboarding'}else{view=v}history.pushState(null,'',location.pathname+location.search+'#/'+view);render()}
function logo(dark=true){return `<div class="brand"><span class="brand-mark"></span><span>orbit</span></div>`}
function initials(name){return (name||'You').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()}
function finishOnboarding(){const name=document.getElementById('onboarding-name').value.trim();if(!name){toast('Add your name to continue');return}state.user.name=name;state.user.useCase=document.getElementById('onboarding-use').value;state.user.goal=document.getElementById('onboarding-goal').value.trim();state.org.name=name+'’s Orbit Workspace';state.onboarded=true;save();view='dashboard';location.hash='#/dashboard';render();toast('Your free workspace is ready')}
function showTour(step=0){state.tourStarted=true;state.tourStep=step;save();const steps=[{title:'Welcome to your workspace',body:'This is your Overview: a quick read on what matters today, what is coming up, and the next best action.',tab:'dashboard',button:'Next →'},{title:'Add your classes first',body:'Start by pasting your class list. Orbit will separate each line into its own class so your assignments stay organized.',tab:'courses',button:'Open Classes →'},{title:'Set grading weights',body:'Tell Orbit how each class is graded. Adjust the weights manually or paste the grading scale from your syllabus so recommendations reflect what matters most.',tab:'priority',button:'Open Priority Adjuster →'},{title:'Add an assignment or exam study task',body:'Now open Planner and add one real assignment, exam, quiz, or study task with a deadline. Orbit will use your grading weights to suggest its priority.',tab:'planner',button:'Open Planner →'},{title:'Plan the week',body:'Review your Calendar to see deadlines and protected time together.',tab:'roadmap',button:'Open Calendar →'},{title:'Protect focus time',body:'Open Focus mode to see how Orbit turns your next task into a distraction-free work session.',tab:'focus',button:'Open Focus mode →'},{title:'You are ready',body:'You have seen the core loop: classes, grading weights, assignments, Calendar, and focus. Analytics will fill in as you work.',tab:'analytics',button:'Finish guided demo'}];const s=steps[step];if(!s)return;let el=document.createElement('div');el.className='tour-backdrop';el.innerHTML='<div class="tour-card"><div class="eyebrow">Guided demo · '+(step+1)+' of '+steps.length+'</div><h2>'+s.title+'</h2><p>'+s.body+'</p><div class="tour-progress">'+steps.map((_,i)=>'<span class="'+(i<=step?'active':'')+'"></span>').join('')+'</div><div class="modal-foot"><button class="secondary" onclick="closeTour()">Skip tour</button><button class="primary" onclick="tourAction('+step+')">'+s.button+'</button></div></div>';document.body.appendChild(el);if(view!==s.tab&&!(step===1&&view==='courses')&&!(step===2&&view==='priority')&&!(step===3&&view==='planner')){closeTour();go(s.tab);setTimeout(()=>showTour(step),250)}}
function tourAction(step){if(step===0){closeTour();showTour(1);return}if(step===1){closeTour();go('courses');toast('Click Paste class list or Add class to continue');return}if(step===2){closeTour();go('priority');toast('Set a grading weight or paste your syllabus scale to continue');return}if(step===3){closeTour();go('planner');toast('Add an assignment or exam study task to continue');return}if(step===4){closeTour();showTour(5);return}if(step===5){closeTour();showTour(6);return}state.tourComplete=true;state.tourStarted=true;save();closeTour();go('dashboard');toast('Guided demo complete — your workspace is ready')}
function completePriorityTour(){if(!(state.tourStarted&&!state.tourComplete&&state.tourStep===2))return;document.querySelectorAll('.tour-backdrop').forEach(el=>el.remove());state.tourStep=3;save();go('planner');setTimeout(()=>showTour(3),250)}
function closeTour(){document.querySelector('.tour-backdrop')?.remove()}
function catchUpItems(){const now=new Date(today+'T12:00:00'),daily=Math.max(0,Number(state.latePolicy.dailyPenalty)||0),cap=Math.max(0,Number(state.latePolicy.maxPenalty)||100);return state.tasks.filter(t=>t.status!=='done'&&t.due&&t.due<today).map(t=>{const daysLate=Math.max(1,Math.ceil((now-new Date(t.due+'T12:00:00'))/86400000)),points=Math.max(1,Number(t.points)||10),deduction=Math.min(points,daysLate*daily,cap),risk=deduction+daysLate*2+(t.priority==='High'?10:t.priority==='Medium'?5:0);return {...t,daysLate,points,deduction,risk}}).sort((a,b)=>b.risk-a.risk||a.due.localeCompare(b.due))}
function saveCatchUpPolicy(){const daily=Math.max(0,Math.min(100,Number(document.getElementById('catchup-daily').value)||0)),cap=Math.max(0,Math.min(100,Number(document.getElementById('catchup-cap').value)||100));state.latePolicy={dailyPenalty:daily,maxPenalty:cap};save();openCatchUp();toast('Catch-up policy saved')}
function openCatchUp(){const overdue=catchUpItems(),upcoming=state.tasks.filter(t=>t.status!=='done'&&t.due&&t.due>=today).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,4),totalRisk=overdue.reduce((sum,t)=>sum+t.deduction,0);let m=document.createElement('div');m.className='modal-backdrop';m.id='catchup-modal';m.innerHTML='<div class="modal catchup-modal"><div class="catchup-head"><div><div class="eyebrow">Recover momentum</div><h2>Catch up</h2><p>Orbit puts overdue work first, estimates the points at risk, then shows what is coming next.</p></div><span class="catchup-count">'+overdue.length+' overdue</span></div><div class="catchup-policy"><div><b>Late-submission policy</b><small>Estimated points deducted per day late.</small></div><label>Points / day<input id="catchup-daily" type="number" min="0" max="100" value="'+state.latePolicy.dailyPenalty+'"></label><label>Max points<input id="catchup-cap" type="number" min="0" max="100" value="'+state.latePolicy.maxPenalty+'"></label><button class="secondary" onclick="saveCatchUpPolicy()">Save policy</button></div><div class="catchup-summary"><div><b>'+overdue.length+'</b><span>overdue assignments</span></div><div><b>'+totalRisk+' pts</b><span>estimated points at risk</span></div></div><h3 class="catchup-section-title">Do these first</h3>'+(overdue.length?overdue.map(t=>'<div class="catchup-item"><div class="catchup-item-main"><div><b>'+t.title+'</b><small>'+course(t.course).code+' · Due '+dateLabel(t.due).full+' · '+t.daysLate+' day'+(t.daysLate===1?'':'s')+' late</small></div><span class="pill '+t.priority.toLowerCase()+'">'+t.priority+'</span></div><div class="catchup-risk"><span>Up to '+t.deduction+' pts deducted</span><span>'+t.points+' pts assignment</span></div><button class="secondary" onclick="closeCatchUp();startTask(\''+t.id+'\')">Start this assignment →</button></div>').join(''):'<div class="empty">You are caught up. Upcoming work is shown below.</div>')+'<h3 class="catchup-section-title">Upcoming after catch-up</h3>'+(upcoming.length?'<div class="catchup-upcoming">'+upcoming.map(t=>'<div><span class="course-dot" style="background:'+course(t.course).color+'"></span><b>'+t.title+'</b><small>'+course(t.course).code+' · Due '+dateLabel(t.due).full+'</small></div>').join('')+'</div>':'<div class="empty">No upcoming assignments yet.</div>')+'<div class="modal-foot"><button class="secondary" onclick="closeCatchUp()">Close</button><button class="primary" onclick="closeCatchUp();go(\'planner\')">Open planner →</button></div></div>';document.body.appendChild(m)}
function catchUpTaskRow(t,isOverdue){return '<div class="catchup-item"><div class="catchup-item-main"><div><b>'+t.title+'</b><small>'+course(t.course).code+' · '+(isOverdue?'Due '+dateLabel(t.due).full+' · '+t.daysLate+' day'+(t.daysLate===1?'':'s')+' late':'Due '+dateLabel(t.due).full)+'</small></div><span class="pill '+t.priority.toLowerCase()+'">'+t.priority+'</span></div><div class="catchup-risk"><span>'+(isOverdue?'Up to '+t.deduction+' pts deducted': 'Upcoming deadline')+'</span><span>'+t.points+' pts assignment</span></div><button class="secondary" onclick="closeCatchUp();startTask(\''+t.id+'\')">Start this assignment →</button></div>'}
function openCatchUpSmart(){const overdue=catchUpItems(),upcoming=state.tasks.filter(t=>t.status!=='done'&&t.due&&t.due>=today).sort((a,b)=>({High:0,Medium:1,Low:2}[a.priority]??1)-({High:0,Medium:1,Low:2}[b.priority]??1)||a.due.localeCompare(b.due)).slice(0,4),totalRisk=overdue.reduce((sum,t)=>sum+t.deduction,0),penaltyFree=overdue.length>0&&totalRisk===0,first=penaltyFree?upcoming:overdue,later=penaltyFree?overdue:upcoming;let m=document.createElement('div');m.className='modal-backdrop';m.id='catchup-modal';m.innerHTML='<div class="modal catchup-modal"><div class="catchup-head"><div><div class="eyebrow">Recover momentum</div><h2>Catch up</h2><p>Orbit puts work with the greatest grade risk first, then shows what is coming next.</p></div><span class="catchup-count">'+overdue.length+' overdue</span></div><div class="catchup-policy"><div><b>Late-submission policy</b><small>Estimated points deducted per day late.</small></div><label>Points / day<input id="catchup-daily" type="number" min="0" max="100" value="'+state.latePolicy.dailyPenalty+'"></label><label>Max points<input id="catchup-cap" type="number" min="0" max="100" value="'+state.latePolicy.maxPenalty+'"></label><button class="secondary" onclick="saveCatchUpPolicy()">Save policy</button></div><div class="catchup-summary"><div><b>'+overdue.length+'</b><span>overdue assignments</span></div><div><b>'+totalRisk+' pts</b><span>estimated points at risk</span></div></div><h3 class="catchup-section-title">'+(penaltyFree?'Protect upcoming deadlines':'Do these first')+'</h3>'+(first.length?first.map(t=>catchUpTaskRow(t,!penaltyFree)).join(''):'<div class="empty">'+(penaltyFree?'No upcoming assignments yet.':'You are caught up. Upcoming work is shown below.')+'</div>')+'<h3 class="catchup-section-title">'+(penaltyFree?'Overdue work':'Upcoming after catch-up')+'</h3>'+(later.length?later.map(t=>catchUpTaskRow(t,penaltyFree)).join(''):'<div class="empty">No more assignments in this queue.</div>')+'<div class="modal-foot"><button class="secondary" onclick="closeCatchUp()">Close</button><button class="primary" onclick="closeCatchUp();go(\'planner\')">Open planner →</button></div></div>';document.body.appendChild(m)}
function catchUpImportBox(){return '<div class="catchup-import"><div><b>Add overdue assignments</b><small>Paste Canvas text or use one assignment per line. Supported formats: Essay: 10/06/26, 10/05/26: Quiz review, or Title | YYYY-MM-DD</small></div><textarea id="catchup-paste" rows="4" oninput="this.style.height=\'auto\';this.style.height=this.scrollHeight+\'px\'" placeholder="Essay: 10/06/26\n10/05/26: Quiz review"></textarea><button class="primary catchup-add-button" onclick="addOverdueAssignmentsFromPaste()">Add overdue work →</button></div>'}
