function normalizeCatchUpDate(raw){const value=(raw||'').trim().replace(/[.\\-]/g,'/'),parts=value.split('/');if(parts.length!==3)return '';let year,month,day;if(parts[0].length===4){year=+parts[0];month=+parts[1];day=+parts[2]}else{month=+parts[0];day=+parts[1];year=+parts[2];if(year<100)year+=2000}if(!year||!month||!day)return '';const date=new Date(year,month-1,day);if(date.getFullYear()!==year||date.getMonth()!==month-1||date.getDate()!==day)return '';return year+'-'+String(month).padStart(2,'0')+'-'+String(day).padStart(2,'0')}
function parseCatchUpLines(text){const datePattern='(\\d{1,4}[\\/-]\\d{1,2}[\\/-]\\d{1,4})',items=[];text.split(/\n+/).map(line=>line.replace(/^[-*•]+\s*/,'').trim()).filter(Boolean).forEach(line=>{let match=line.match(new RegExp('^(.+?)\\s*(?:\\||\\s+-\\s+|:)\\s*'+datePattern+'$','i'));if(match){items.push({title:match[1].trim(),due:normalizeCatchUpDate(match[2]),points:10,courseCode:'',courseName:''});return}match=line.match(new RegExp('^'+datePattern+'\\s*:\\s*(.+)$','i'));if(match)items.push({title:match[2].trim(),due:normalizeCatchUpDate(match[1]),points:10,courseCode:'',courseName:''})});return items.filter(item=>item.title&&item.due)}
function addOverdueAssignmentsFromPaste(){const text=document.getElementById('catchup-paste')?.value||'',canvas=parseImportedAssignments(text).map(item=>({title:item.title,due:item.due,points:item.points,courseCode:item.courseCode,courseName:item.courseName})),items=[...canvas,...parseCatchUpLines(text)].filter((item,index,array)=>array.findIndex(other=>other.title.toLowerCase()===item.title.toLowerCase()&&other.due===item.due)===index),overdue=items.filter(item=>item.due<today);if(!overdue.length){toast('No past-due assignments found. Check the date format and try again.');return}overdue.forEach(item=>{let c=state.courses.find(x=>item.courseCode&&x.code.toLowerCase()===item.courseCode.toLowerCase());if(!c&&item.courseCode){c={id:'c'+Date.now()+Math.random().toString(16).slice(2),name:item.courseName||item.courseCode,code:item.courseCode,color:['#79a9ff','#c29cff','#ffad72','#65d6b0'][state.courses.length%4],teacher:'Imported overdue work'};state.courses.push(c)}state.tasks.push({id:'t'+Date.now()+Math.random().toString(16).slice(2),title:item.title,type:'Assignment',course:c?.id||state.courses[0]?.id||'',due:item.due,points:item.points||10,estimate:60,difficulty:3,priority:'High',status:'todo',progress:0,subtasks:1})});save();closeCatchUp();render();toast(overdue.length+' overdue assignment'+(overdue.length===1?'':'s')+' added')}
openCatchUp=()=>{document.getElementById('catchup-modal')?.remove();openCatchUpSmart();const modal=document.getElementById('catchup-modal'),panel=modal?.querySelector('.modal'),policy=modal?.querySelector('.catchup-policy'),count=modal?.querySelector('.catchup-count');if(modal&&panel){const noOverdue=count?.textContent.trim()==='0 overdue';modal.querySelectorAll('.catchup-item').forEach(el=>{if(noOverdue||/Upcoming deadline/i.test(el.textContent))el.remove()});modal.querySelectorAll('.catchup-upcoming').forEach(el=>el.remove());if(noOverdue){count.remove();modal.querySelector('.catchup-summary')?.remove();modal.querySelectorAll('.empty').forEach(el=>{if(/caught up|No more assignments/i.test(el.textContent))el.remove()})}modal.setAttribute('onclick','if(event.target===event.currentTarget)this.remove()');panel.insertAdjacentHTML('afterbegin','<button class="modal-close" aria-label="Close Catch up" onclick="closeCatchUp()">×</button>');modal.querySelectorAll('.catchup-section-title').forEach(el=>el.remove());modal.querySelector('.modal-foot')?.querySelectorAll('button').forEach(button=>{if(button.textContent.trim()==='Close')button.remove()});modal.querySelector('.modal-foot')?.insertAdjacentHTML('afterbegin','<button class="primary catchup-save" onclick="saveCatchUpAndClose()">Save</button>')}if(policy){policy.insertAdjacentHTML('beforeend','<button class="secondary catchup-no-policy" onclick="setNoLatePolicy()">No policy</button>');policy.insertAdjacentHTML('afterend',catchUpImportBox())}}
