function appShellFresh(){let nav=[['dashboard','Overview','grid'],['planner','Planner','check'],['roadmap','Roadmap','calendar'],['focus','Focus mode','target'],['courses','Courses','book'],['analytics','Analytics','chart']];return '<div class="app-shell"><aside class="sidebar">'+logo()+'<button class="workspace-switch" onclick="go(\'settings\')"><span class="avatar">'+initials(state.user.name)+'</span><span><small>Workspace</small><strong>'+state.org.name+'</strong></span></button><div class="nav-label">Workspace</div>'+nav.map(n=>'<button class="nav-link '+(view===n[0]?'active':'')+'" data-tour="'+n[0]+'" onclick="go(\''+n[0]+'\')">'+icons[n[2]]+'<span>'+n[1]+'</span></button>').join('')+'<div class="nav-label">Manage</div><button class="nav-link '+(view==='settings'?'active':'')+'" onclick="go(\'settings\')">'+icons.settings+'<span>Settings</span></button><div class="side-bottom"><div class="profile"><span class="avatar">'+initials(state.user.name)+'</span><span class="profile-info"><b style="font-size:12px;color:#fff">'+state.user.name+'</b><small>Free demo workspace</small></span></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><span>Workspace</span> <span style="margin:0 6px;color:#c1cad7">/</span> <strong>'+(({dashboard:'Overview',planner:'Assignment planner',roadmap:'Weekly roadmap',focus:'Focus mode',courses:'Courses',analytics:'Analytics',settings:'Settings'})[view]||'Overview')+'</strong></div><div class="top-actions"><button class="icon-btn" onclick="toast(\'You are all caught up\')">'+icons.bell+'</button><button class="secondary" onclick="showTour(0)">? Guided tour</button><button class="secondary" onclick="openModal()">＋ Add task</button><button class="primary" onclick="go(\'focus\')">'+icons.target+' Start focus</button></div></header><div class="content">'+({dashboard:dashboardFresh,planner:planner,roadmap:roadmap,focus:focus,courses:courses,analytics:analytics,settings:settings}[view]||dashboardFresh)()+'</div></main></div>'}
function plannerFresh(){return '<div class="page-head"><div><div class="eyebrow">Your workload, made workable</div><h1>Assignment planner</h1><p>Every deadline in one calm, prioritized view.</p></div><div class="page-actions"><button class="secondary" onclick="openImportModal()">↥ Paste from Canvas</button><button class="primary" onclick="openModal()">＋ Add assignment</button></div></div><div class="card"><div class="toolbar"><div class="search">'+icons.search+'<input id="task-search" placeholder="Search assignments..." oninput="filterTasks()"></div><div class="filters"><select id="course-filter" onchange="filterTasks()"><option value="all">All courses</option>'+state.courses.map(c=>'<option value="'+c.id+'">'+c.code+'</option>').join('')+'</select><select id="status-filter" onchange="filterTasks()"><option value="all">All status</option><option value="todo">In progress</option><option value="done">Completed</option></select><select id="priority-filter" onchange="filterTasks()"><option value="all">All priority</option><option>High</option><option>Medium</option><option>Low</option></select></div></div><div id="task-table"><table class="table"><thead><tr><th style="width:40%">Assignment</th><th>Course</th><th>Due date</th><th>Time</th><th>Priority</th><th></th></tr></thead><tbody>'+state.tasks.map(tableTask).join('')+'</tbody></table>'+(state.tasks.length?'':'<div class="empty">No assignments yet. Add one manually or paste your Canvas assignment list.</div>')+'</div></div>'}
function parseImportedAssignments(text){const clean=text.replace(/\r/g,' ').replace(/\n+/g,' ').replace(/\s+/g,' ').replace(/\bsvg\b/gi,'');const pattern=/\[\*\*(.+?)\*\*\]\((https?:\/\/[^)]+)\)\s*([^|]+?)\|\s*\[Go to course\]\([^)]+\)\s*(\d+)\s*pts\s*\*\*(\d{1,2}\/\d{1,2}\/\d{4})\s+(\d{1,2}:\d{2}\s*[AP]M)\*\*/gi;let matches=[],m;while((m=pattern.exec(clean))){const courseText=m[3].trim();const codeMatch=courseText.match(/^(.+?)(?:\s*\([^)]*\))?\s+([^()]+)$/);const code=(codeMatch?codeMatch[1]:courseText).trim();const courseName=(codeMatch?codeMatch[2]:courseText).trim();const [month,day,year]=m[5].split('/');const iso=year+'-'+month.padStart(2,'0')+'-'+day.padStart(2,'0');matches.push({title:m[1].trim(),url:m[2],courseCode:code,courseName,due:iso,displayDue:m[5]+' '+m[6],points:+m[4]})}return matches}
function openImportModal(){let m=document.createElement('div');m.className='modal-backdrop';m.id='import-modal';m.innerHTML='<div class="modal import-modal"><h2>Paste assignments</h2><p>Copy your assignment list from Canvas and paste it below. Orbit will extract titles, courses, points, and due dates.</p><div class="field"><label>Canvas assignment text</label><textarea id="import-text" placeholder="Paste your Canvas assignment list here..." style="min-height:150px"></textarea></div><div id="import-preview" class="import-preview hidden"></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'import-modal\').remove()">Cancel</button><button class="secondary" onclick="previewImport()">Preview</button><button class="primary" onclick="importAssignments()">Import assignments →</button></div></div>';document.body.appendChild(m)}
function previewImport(){const parsed=parseImportedAssignments(document.getElementById('import-text').value);const box=document.getElementById('import-preview');box.classList.remove('hidden');box.innerHTML=parsed.length?'<b>'+parsed.length+' assignments found</b>'+parsed.map(x=>'<div class="import-row"><span>'+x.title+'</span><small>'+x.courseCode+' · '+x.displayDue+'</small></div>').join(''):'<span>No assignments found yet. Make sure the pasted text includes the Canvas title, course, points, and due date.'}
function importAssignments(){const parsed=parseImportedAssignments(document.getElementById('import-text').value);if(!parsed.length){toast('Preview could not find any assignments');return}parsed.forEach(item=>{let c=state.courses.find(x=>x.code.toLowerCase()===item.courseCode.toLowerCase());if(!c){c={id:'c'+Date.now()+Math.random().toString(16).slice(2),name:item.courseName,code:item.courseCode,color:['#79a9ff','#c29cff','#ffad72','#65d6b0'][state.courses.length%4],teacher:'Imported from Canvas'};state.courses.push(c)}state.tasks.push({id:'t'+Date.now()+Math.random().toString(16).slice(2),title:item.title,type:'Assignment',course:c.id,due:item.due,estimate:60,difficulty:3,priority:'Medium',status:'todo',progress:0,subtasks:1,points:item.points,externalUrl:item.url})});save();document.getElementById('import-modal').remove();render();toast(parsed.length+' assignment'+(parsed.length===1?'':'s')+' imported from Canvas');if(state.tourStarted&&!state.tourComplete&&state.tourStep===3)setTimeout(()=>showTour(4),400)}
function parseCourseList(text){return text.split(/\r?\n/).map(line=>line.replace(/^\s*[-•*]\s*/,'').replace(/^\[([^\]]+)\]\([^)]+\)\s*/,'').replace(/\s+/g,' ').trim()).filter(Boolean).map(line=>{const codeMatch=line.match(/^([A-Z]{2,6}\s*\d{3,5}(?:\.\d+)?)/i);const code=codeMatch?codeMatch[1].replace(/\s+/g,' ').trim():'CLASS';const name=codeMatch?line.slice(codeMatch[1].length).replace(/^\s*(?:\([^)]*\))?\s*/,'').trim()||line:line;return {code,name}}).filter(x=>x.name)}
function openCourseImportModal(){let m=document.createElement('div');m.className='modal-backdrop';m.id='course-import-modal';m.innerHTML='<div class="modal"><h2>Add your courses</h2><p>Paste one course per line. Orbit will split the list and create a course card for each one.</p><div class="field"><label>Course list</label><textarea id="course-import-text" placeholder="CS 4800.01 (F26-Regular) Software Engineering&#10;CS 4230.01 (F26-Regular) Social Computing" style="min-height:150px"></textarea></div><div id="course-import-preview" class="import-preview hidden"></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'course-import-modal\').remove()">Cancel</button><button class="secondary" onclick="previewCourseImport()">Preview</button><button class="primary" onclick="importCourses()">Add courses →</button></div></div>';document.body.appendChild(m)}
function previewCourseImport(){const parsed=parseCourseList(document.getElementById('course-import-text').value);const box=document.getElementById('course-import-preview');box.classList.remove('hidden');box.innerHTML=parsed.length?'<b>'+parsed.length+' courses found</b>'+parsed.map(x=>'<div class="import-row"><span>'+x.name+'</span><small>'+x.code+'</small></div>').join(''):'<span>No courses found. Paste one course per line.</span>'}
function importCourses(){const parsed=parseCourseList(document.getElementById('course-import-text').value);if(!parsed.length){toast('Paste at least one course to continue');return}parsed.forEach(item=>{if(!state.courses.some(c=>c.code.toLowerCase()===item.code.toLowerCase()))state.courses.push({id:'c'+Date.now()+Math.random().toString(16).slice(2),name:item.name,code:item.code,color:['#79a9ff','#c29cff','#ffad72','#65d6b0'][state.courses.length%4],teacher:'Added by you'})});save();document.getElementById('course-import-modal').remove();render();toast(parsed.length+' course'+(parsed.length===1?'':'s')+' added');if(state.tourStarted&&!state.tourComplete&&state.courses.length>0){setTimeout(()=>showTour(2),400)}}
function coursesFresh(){return '<div class="page-head"><div><div class="eyebrow">Your academic orbit</div><h1>Courses</h1><p>Start with your course list, then attach assignments to the right place.</p></div><div class="page-actions"><button class="secondary" onclick="openCourseImportModal()">↥ Paste course list</button><button class="primary" onclick="toast(\'Use Paste course list to add your first course\')">＋ Add course</button></div></div>'+(state.courses.length?'<div class="grid grid-3">'+state.courses.map(c=>{let ts=state.tasks.filter(t=>t.course===c.id),pct=ts.length?Math.round(ts.reduce((a,t)=>a+t.progress,0)/ts.length):0;return '<div class="card course-card"><div class="course-banner" style="background:'+c.color+'"></div><h3>'+c.name+'</h3><p>'+c.code+' · '+c.teacher+'</p><div style="margin-top:22px"><div class="stat-top">Course progress <b style="color:var(--navy)">'+pct+'%</b></div><div class="progress" style="margin-top:8px"><span style="width:'+pct+'%;background:'+c.color+'"></span></div></div><div class="course-meta"><span>'+ts.length+' assignments</span><span>'+(!ts.length?'Ready for work':'In progress')+'</span></div></div>'}).join('')+'</div>':'<div class="card empty-course"><div class="empty">No courses yet. Paste your course list to build your workspace in seconds.</div></div>')}
function openClassModal(){let m=document.createElement('div');m.className='modal-backdrop';m.id='class-modal';m.innerHTML='<div class="modal"><h2>Add a class</h2><p>Add one class manually, or use Paste class list to add several at once.</p><div class="field"><label>Class name</label><input id="class-name" placeholder="e.g. Software Engineering"></div><div class="field" style="margin-top:12px"><label>Class code</label><input id="class-code" placeholder="e.g. CS 4800.01"></div><div class="field" style="margin-top:12px"><label>Instructor (optional)</label><input id="class-teacher" placeholder="e.g. Professor Smith"></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'class-modal\').remove()">Cancel</button><button class="primary" onclick="addClass()">Add class →</button></div></div>';document.body.appendChild(m)}
function addClass(){const name=document.getElementById('class-name').value.trim(),code=document.getElementById('class-code').value.trim()||'CLASS';if(!name){toast('Add a class name to continue');return}state.courses.push({id:'c'+Date.now(),name,code,teacher:document.getElementById('class-teacher').value.trim()||'Added by you',color:['#79a9ff','#c29cff','#ffad72','#65d6b0'][state.courses.length%4]});save();document.getElementById('class-modal').remove();render();toast('Class added');if(state.tourStarted&&!state.tourComplete&&state.courses.length>0){setTimeout(()=>showTour(2),400)}}
function classWeights(id){return state.grading[id]||{exam:null,project:null,quiz:null,homework:null}}
function updateWeight(id,key,value){state.grading[id] ||= {exam:null,project:null,quiz:null,homework:null};state.grading[id][key]=Math.max(0,Math.min(100,+value||0));save()}
function priorityForAssignment(courseId,title,type){const weights=classWeights(courseId),text=((title||'')+' '+(type||'')).toLowerCase();let category=text.includes('exam')||text.includes('midterm')||text.includes('final')?'exam':text.includes('project')||text.includes('paper')||text.includes('essay')?'project':text.includes('quiz')?'quiz':'homework',weight=weights[category]||0;return weight>=35?'High':weight>=20?'Medium':'Low'}
function setNewPriorityAuto(){const courseId=document.getElementById('new-course').value,title=document.getElementById('new-title').value,type='Assignment',priority=priorityForAssignment(courseId,title,type);document.getElementById('new-priority').value=priority;toast('Priority set to '+priority+' based on class grading')}
function parseGradingText(text){const source=(text||'').replace(/\u2013|\u2014/g,'-'),aliases={exam:['exams?','midterms?','finals?'],project:['projects?','papers?','essays?','presentations?'],quiz:['quizzes?','quizes?','tests?'],homework:['homework','assignments?','participation','classwork']},result={};Object.entries(aliases).forEach(([key,words])=>{const label=words.join('|'),before=new RegExp('(?:'+label+')\\b[^\\d%]{0,24}(\\d{1,3})\\s*%?','i'),after=new RegExp('(\\d{1,3})\\s*%?[^\\d%]{0,8}(?:'+label+')\\b','i'),match=source.match(before)||source.match(after);if(match)result[key]=Math.min(100,Number(match[1]))});return result}
function openGradingImportModal(courseId){const c=course(courseId);let m=document.createElement('div');m.className='modal-backdrop';m.id='grading-import-modal';m.innerHTML=`<div class="modal grading-import-modal"><h2>Paste grading scale</h2><p>Paste the grading breakdown from your syllabus for <b>${c.name}</b>. Orbit will find percentages for exams, projects, quizzes, and homework.</p><div class="field"><label>Grading scale or syllabus text</label><textarea id="grading-import-text" placeholder="Exams: 40%\nProjects: 30%\nQuizzes: 15%\nHomework: 15%" style="min-height:155px"></textarea></div><div id="grading-import-preview" class="import-preview hidden"></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById('grading-import-modal').remove()">Cancel</button><button class="secondary" onclick="previewGradingImport()">Preview weights</button><button class="primary" onclick="applyGradingImport('${courseId}')">Apply to ${c.code} →</button></div></div>`;document.body.appendChild(m)}
function previewGradingImport(){const parsed=parseGradingText(document.getElementById('grading-import-text').value),labels={exam:'Exams',project:'Projects / papers',quiz:'Quizzes',homework:'Homework'},box=document.getElementById('grading-import-preview');box.classList.remove('hidden');box.innerHTML=Object.keys(parsed).length?'<b>Weights found</b><div class="grading-preview-grid">'+Object.entries(parsed).map(([key,value])=>'<span>'+labels[key]+'</span><strong>'+value+'%</strong>').join('')+'</div>':'<span>No grading percentages found yet. Try text like “Exams: 40%, Projects: 30%.”</span>'}
function applyGradingImport(courseId){const parsed=parseGradingText(document.getElementById('grading-import-text').value);if(!Object.keys(parsed).length){toast('Paste grading percentages before applying');return}state.grading[courseId]={...classWeights(courseId),...parsed};save();document.getElementById('grading-import-modal').remove();render();toast('Grading scale imported and saved');advancePriorityTour()}
function priorityCard(c){const w=classWeights(c.id),total=[w.exam,w.project,w.quiz,w.homework].reduce((sum,value)=>sum+Number(value||0),0);return `<div class="card priority-card"><div class="priority-card-head"><div><span class="course-dot" style="background:${c.color}"></span><h2>${c.name}</h2><p>${c.code} · Current weighting: ${total}%</p></div><span class="pill ${total===100?'low':'medium'}">${total===100?'Balanced':'Check total'}</span></div><div class="weight-grid"><label>Exams <input type="number" min="0" max="100" value="${w.exam??''}" onchange="updateWeight('${c.id}','exam',this.value)"><small>%</small></label><label>Projects / papers <input type="number" min="0" max="100" value="${w.project??''}" onchange="updateWeight('${c.id}','project',this.value)"><small>%</small></label><label>Quizzes <input type="number" min="0" max="100" value="${w.quiz??''}" onchange="updateWeight('${c.id}','quiz',this.value)"><small>%</small></label><label>Homework <input type="number" min="0" max="100" value="${w.homework??''}" onchange="updateWeight('${c.id}','homework',this.value)"><small>%</small></label></div><div class="priority-card-actions"><div class="reason-box">${total===100?'Auto-set will prioritize higher-impact work first.':'These weights add up to '+total+'%. Add or adjust weights until they total 100%.'}</div></div></div>`}
function savePriorityAdjustments(){save();toast('Priority settings saved')}
function openPriorityPasteModal(){if(!state.courses.length){toast('Add a class before importing a grading scale');return}let m=document.createElement('div');m.className='modal-backdrop';m.id='grading-import-modal';m.innerHTML='<div class="modal grading-import-modal"><h2>Paste grading scale</h2><p>Paste grading details from a syllabus and Orbit will extract the percentages.</p><div class="field"><label>Class</label><select id="priority-import-course">'+state.courses.map(c=>'<option value="'+c.id+'">'+c.code+' · '+c.name+'</option>').join('')+'</select></div><div class="field" style="margin-top:12px"><label>Grading scale or syllabus text</label><textarea id="grading-import-text" placeholder="Exams: 40%\nProjects: 30%\nQuizzes: 15%\nHomework: 15%" style="min-height:155px"></textarea></div><div id="grading-import-preview" class="import-preview hidden"></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'grading-import-modal\').remove()">Cancel</button><button class="secondary" onclick="previewGradingImport()">Preview weights</button><button class="primary" onclick="applyPriorityPaste()">Apply weights →</button></div></div>';document.body.appendChild(m)}
function applyPriorityPaste(){const courseId=document.getElementById('priority-import-course').value;applyGradingImport(courseId)}
function priorityFresh(){const cards=state.courses.map(priorityCard).join(''),tourDone=state.tourStarted&&!state.tourComplete&&state.tourStep===2;return `<div class="page-head"><div><div class="eyebrow">Make recommendations fit your classes</div><h1>Priority adjuster</h1><p>Set grading weights for each class so Orbit knows what work carries the most impact.</p></div><div class="page-actions"><button class="secondary" onclick="savePriorityAdjustments()">Save</button><button class="primary" onclick="openPriorityPasteModal()">↥ Paste grading scale</button></div></div>${cards||'<div class="card empty-state-large"><div class="empty">Add your classes first, then set their grading weights here.</div></div>'}${tourDone?'<div class="tour-step-actions"><div><b>Finished setting priorities?</b><small>Click Done when you are ready to add your first assignment.</small></div><button class="primary tour-done-button" onclick="completePriorityTour()">Done →</button></div>':''}`}
function planHub(){return '<div class="page-head"><div><div class="eyebrow">Your academic command center</div><h1>Plan</h1><p>Organize deadlines, classes, priorities, and protected time from one place.</p></div><button class="primary" onclick="openModal()">＋ Add assignment</button></div><div class="plan-hub-grid"><button class="card plan-hub-card" onclick="go(\'planner\')"><span class="plan-hub-icon">✓</span><span><b>Assignments</b><small>Add, sort, complete, or paste from Canvas.</small></span><span class="plan-hub-arrow">→</span></button><button class="card plan-hub-card" onclick="go(\'calendar\')"><span class="plan-hub-icon">▦</span><span><b>Calendar</b><small>See deadlines and time blocks in one view.</small></span><span class="plan-hub-arrow">→</span></button><button class="card plan-hub-card" onclick="go(\'courses\')"><span class="plan-hub-icon">'+icons.book+'</span><span><b>Classes</b><small>Manage classes and see course progress.</small></span><span class="plan-hub-arrow">→</span></button><button class="card plan-hub-card" onclick="go(\'priority\')"><span class="plan-hub-icon">✦</span><span><b>Priority adjuster</b><small>Set grading weights and auto-prioritize work.</small></span><span class="plan-hub-arrow">→</span></button><button class="card plan-hub-card catchup-plan-card" onclick="openCatchUp()"><span class="plan-hub-icon">↺</span><span><b>Catch up</b><small>Prioritize overdue work by points at risk and protect upcoming deadlines.</small></span><span class="plan-hub-arrow">→</span></button></div><div class="plan-hub-tip"><span>'+icons.spark+'</span><div><b>Start with what is fixed.</b><p>Add your classes and commitments first, then use assignments and Calendar to plan the gaps.</p></div></div>'}
function roadmapFresh(){return '<div class="page-head"><div><div class="eyebrow">Your next seven days</div><h1>Weekly roadmap</h1><p>Orbit will distribute your assignments across a clear calendar.</p></div><div class="page-actions"><button class="secondary" onclick="toast(\'Week view is coming soon\')">Week view</button><button class="primary" onclick="go(\'planner\')">＋ Add work</button></div></div><div class="card calendar-card"><div class="calendar-toolbar"><button class="icon-btn" onclick="toast(\'Previous month\')">‹</button><h2>October 2026</h2><button class="icon-btn" onclick="toast(\'Next month\')">›</button></div><div class="calendar-grid calendar-weekdays">'+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>'<div>'+d+'</div>').join('')+'</div><div class="calendar-grid">'+calendarCells()+'</div><div class="calendar-legend"><span><i style="background:#79a9ff"></i> Class assignment</span><span><i style="background:var(--mint-strong)"></i> Personal target</span></div></div>'}
function calendarCells(){const now=new Date(),year=now.getFullYear(),month=now.getMonth(),first=new Date(year,month,1).getDay(),days=new Date(year,month+1,0).getDate();let cells=[];for(let i=0;i<first;i++)cells.push('<div class="calendar-day muted-day"></div>');for(let day=1;day<=days;day++){const iso=year+'-'+String(month+1).padStart(2,'0')+'-'+String(day).padStart(2,'0'),items=state.tasks.filter(t=>t.due===iso);cells.push('<div class="calendar-day '+(iso===today?'today-day':'')+'" onclick="openDayScheduleModal(\''+iso+'\')" title="Click to view this date\'s hourly schedule"><b>'+day+'</b>'+(items.length?items.map(t=>'<button class="calendar-task" style="border-left-color:'+(t.type==='Study'?'#2bb673':course(t.course).color)+'" onclick="event.stopPropagation();go(\'planner\')" title="'+t.title+'">'+t.title+'</button>').join(''):'')+'</div>')}return cells.join('')}
function isoForWeekday(day){let d=new Date(today+'T12:00:00');d.setDate(d.getDate()+(day-d.getDay()));return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function selectCalendarDate(iso){selectedScheduleDate=iso;render();setTimeout(()=>document.getElementById('calendar-time-blocks')?.scrollIntoView({behavior:'smooth',block:'start'}),0)}
function scheduleCell(date,hour){const blocks=state.timeBlocks.filter(b=>b.date===date&&Number(b.start.split(':')[0])===hour);return '<div class="hour-cell add-time-cell" onclick="openTimeBlockModal(\''+date+'\','+hour+')">'+(blocks.length?blocks.map(b=>'<button class="time-block '+b.kind+'" title="'+b.title+'" onclick="event.stopPropagation();openTimeBlockModal(\''+b.date+'\','+Number(b.start.split(':')[0])+')"><b>'+b.title+'</b><small>'+b.start+'–'+b.end+'</small></button>').join(''):'<span>＋ Add</span>')+'</div>'}
function singleDaySchedule(date){const hours=Array.from({length:15},(_,i)=>i+8);return '<div class="hourly-single-grid">'+hours.map(hour=>'<div class="hour-label">'+formatHour(hour)+'</div>'+scheduleCell(date,hour)).join('')+'</div>'}
function weeklySchedule(){const days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'],hours=Array.from({length:15},(_,i)=>i+8);return '<div class="hourly-grid hourly-head"><div></div>'+days.map((d,i)=>'<div>'+d+'<small>'+dateLabel(isoForWeekday(i)).full+'</small></div>').join('')+'</div><div class="hourly-grid">'+hours.map(hour=>'<div class="hour-label">'+formatHour(hour)+'</div>'+days.map((_,day)=>scheduleCell(isoForWeekday(day),hour)).join('')).join('')+'</div>'}
function openDayScheduleModal(date){document.getElementById('day-schedule-modal')?.remove();let m=document.createElement('div');m.className='modal-backdrop';m.id='day-schedule-modal';m.setAttribute('onclick','if(event.target===event.currentTarget)this.remove()');m.innerHTML='<div class="modal day-schedule-modal"><button class="modal-close" aria-label="Close hourly schedule" onclick="document.getElementById(\'day-schedule-modal\').remove()">×</button><div class="day-schedule-title"><div><div class="eyebrow">Selected date</div><h2>Hourly schedule · '+dateLabel(date).full+'</h2><p>Add classes, study sessions, work, or personal commitments for this date.</p></div></div><div class="day-schedule-scroll">'+singleDaySchedule(date)+'</div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'day-schedule-modal\').remove()">Close</button><button class="primary" onclick="document.getElementById(\'day-schedule-modal\').remove();openTimeBlockModal(\''+date+'\')">＋ Add time block</button></div></div>';document.body.appendChild(m)}
function timePlannerFresh(){const days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'],hours=Array.from({length:15},(_,i)=>i+8);return '<div class="page-head"><div><div class="eyebrow">Shape the time around your work</div><h1>Time planner</h1><p>Block classes, commitments, study sessions, and homework into a schedule you can actually follow.</p></div><button class="primary" onclick="openTimeBlockModal()">＋ Add time block</button></div><div class="card hourly-card"><div class="hourly-grid hourly-head"><div></div>'+days.map(d=>'<div>'+d+'</div>').join('')+'</div><div class="hourly-grid">'+hours.map(hour=>'<div class="hour-label">'+formatHour(hour)+'</div>'+days.map((_,day)=>{const date=isoForWeekday(day),blocks=state.timeBlocks.filter(b=>b.date===date&&Number(b.start.split(':')[0])===hour);return '<div class="hour-cell add-time-cell" onclick="openTimeBlockModal(\''+date+'\','+hour+')">'+(blocks.length?blocks.map(b=>'<button class="time-block '+b.kind+'" title="'+b.title+'" onclick="event.stopPropagation();openTimeBlockModal(\''+b.date+'\','+Number(b.start.split(':')[0])+')"><b>'+b.title+'</b><small>'+b.start+'–'+b.end+'</small></button>').join(''):'<span>＋ Add</span>')+'</div>'}).join('')).join('')+'</div></div><div class="time-planner-note"><span>${icons.spark}</span><div><b>Plan around your fixed commitments first.</b><p>Once classes and other blocks are in place, use Planner and Roadmap to fit study time into the gaps.</p></div></div>'}
function calendarFresh(){const now=new Date(),monthLabel=now.toLocaleString('en-US',{month:'long',year:'numeric'}),days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];return '<div class="page-head"><div><div class="eyebrow">Deadlines and protected time</div><h1>Calendar</h1><p>See what is due and when you have time to do it.</p></div><div class="page-actions"><button class="secondary" onclick="document.getElementById(\'calendar-time-blocks\').scrollIntoView({behavior:\'smooth\'})">↓ Weekly schedule</button><button class="primary calendar-add-assignment" onclick="openModal()">＋ Add assignment</button></div></div><div class="card calendar-card"><div class="card-title"><h2>Deadlines</h2><span class="pill blue">'+monthLabel+'</span></div><div class="calendar-grid calendar-weekdays">'+days.map(d=>'<div>'+d+'</div>').join('')+'</div><div class="calendar-grid">'+calendarCells()+'</div><div class="calendar-legend"><span><i style="background:#79a9ff"></i> Class assignment</span><span><i style="background:#2bb673"></i> Studying</span><span><i style="background:var(--mint-strong)"></i> Orbit target · '+dateLabel(today).full+'</span></div></div><div class="card hourly-card calendar-time-card" id="calendar-time-blocks"><div class="card-title"><div><h2>Weekly hourly schedule</h2><small>Click any time cell to add a block.</small></div><span class="pill low">This week</span></div>'+weeklySchedule()+'</div>'}
function formatHour(hour){const suffix=hour>=12?'PM':'AM',display=hour>12?hour-12:hour===0?12:hour;return display+':00 '+suffix}
function openTimeBlockModal(selectedDate=today,selectedHour=9){const selected=new Date(selectedDate+'T12:00:00'),selectedDay=selected.getDay(),startHour=Math.max(0,Math.min(23,Number(selectedHour)||9)),endHour=Math.min(23,startHour+1),startValue=String(startHour).padStart(2,'0')+':00',endValue=String(endHour).padStart(2,'0')+':00';let m=document.createElement('div');m.className='modal-backdrop';m.id='time-block-modal';m.innerHTML='<div class="modal"><h2>Add a time block</h2><p>Tell Orbit when you are unavailable or when you want to protect study time.</p><div class="form-grid"><div class="field full"><label>What is this block?</label><input id="block-title" placeholder="e.g. CS 4800 lecture or study for midterm"></div><div class="field"><label>Date</label><input id="block-date" type="date" value="'+selectedDate+'" onchange="this.dataset.day=new Date(this.value+\'T12:00:00\').getDay()" data-day="'+selectedDay+'"></div><div class="field"><label>Type</label><select id="block-kind"><option value="class">Class</option><option value="study">Study</option><option value="work">Work</option><option value="personal">Personal</option></select></div><div class="field"><label>Start</label><input id="block-start" type="time" value="'+startValue+'"></div><div class="field"><label>End</label><input id="block-end" type="time" value="'+endValue+'"></div></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'time-block-modal\').remove()">Cancel</button><button class="primary" onclick="addTimeBlock()">Add block →</button></div></div>';document.body.appendChild(m)}
function addTimeBlock(){const title=document.getElementById('block-title').value.trim(),date=document.getElementById('block-date').value,start=document.getElementById('block-start').value,end=document.getElementById('block-end').value;if(!title||!date||!start||!end){toast('Add a title, date, start time, and end time');return}if(end<=start){toast('End time must be after start time');return}state.timeBlocks.push({id:'b'+Date.now(),title,date,day:new Date(date+'T12:00:00').getDay(),kind:document.getElementById('block-kind').value,start,end});save();document.getElementById('time-block-modal').remove();render();toast('Time block added')}
function focusFresh(){return '<div class="page-head"><div><div class="eyebrow">Protect your attention</div><h1>Focus mode</h1><p>Start a session when you are ready to work on something real.</p></div></div><div class="grid grid-2"><div class="focus-card card"><div class="timer">25:00</div><div class="timer-label">Ready when you are</div><div class="timer-controls"><button onclick="toggleTimer()">Start session</button><button class="secondary-dark" onclick="resetTimer()">Reset</button></div></div><div class="card empty-state-large"><div class="empty">Choose an assignment in Planner, then start a focus session. Your statistics will appear here after you complete real sessions.</div></div></div>'}
function analyticsFresh(){return '<div class="page-head"><div><div class="eyebrow">Your momentum, measured</div><h1>Analytics</h1><p>Orbit will turn your completed work and focus sessions into useful patterns.</p></div></div><div class="card empty-state-large"><div class="empty">No analytics yet. Add courses and assignments, complete a task, or finish a focus session to start building your personal productivity picture.</div></div>'}
function focusFlexible(){let mins=Math.floor(timer.seconds/60).toString().padStart(2,'0'),secs=(timer.seconds%60).toString().padStart(2,'0'),isBreak=timer.mode==='break';return '<div class="page-head"><div><div class="eyebrow">Protect your attention</div><h1>Focus mode</h1><p>Choose a work block or a break that fits your energy.</p></div><button class="secondary" onclick="toast(\'Focus preferences saved for this session\')">⚙ Preferences</button></div><div class="grid grid-2"><div class="focus-card card"><div class="timer">'+mins+':'+secs+'</div><div class="timer-label">'+(isBreak?'Break time · recharge before the next block':timer.running?'Deep work in progress':'Ready when you are')+'</div><div class="timer-controls"><button onclick="toggleTimer()">'+(timer.running?'Pause':isBreak?'Start break':'Start focus')+'</button><button class="secondary-dark" onclick="resetTimer()">Reset</button></div></div><div class="card"><div class="card-title"><h2>Session length</h2><span class="pill '+(isBreak?'low':'blue')+'">'+(isBreak?'Break':'Focus')+'</span></div><div class="timer-options"><button class="timer-option '+(!isBreak&&timer.preset===25?'selected':'')+'" onclick="setTimer(25,\'focus\')"><b>25 min</b><span>Classic Pomodoro</span></button><button class="timer-option '+(!isBreak&&timer.preset===60?'selected':'')+'" onclick="setTimer(60,\'focus\')"><b>1 hour</b><span>Deep work block</span></button><button class="timer-option '+(!isBreak&&timer.custom?'selected':'')+'" onclick="openCustomTimer(\'focus\')"><b>Custom</b><span>Choose your minutes</span></button></div><div class="card-title" style="margin-top:25px"><h2>Break length</h2><span class="pill low">Recovery</span></div><div class="timer-options"><button class="timer-option '+(isBreak&&timer.preset===10?'selected':'')+'" onclick="setTimer(10,\'break\')"><b>10 min</b><span>Quick reset</span></button><button class="timer-option '+(isBreak&&timer.preset===15?'selected':'')+'" onclick="setTimer(15,\'break\')"><b>15 min</b><span>Longer recharge</span></button><button class="timer-option '+(isBreak&&timer.custom?'selected':'')+'" onclick="openCustomTimer(\'break\')"><b>Custom</b><span>Choose your minutes</span></button></div></div></div><div class="grid grid-3" style="margin-top:18px"><div class="mini-stat"><span>Focus today</span><b>'+Math.floor(state.focus/60)+'m</b><span>Complete sessions to build your total</span></div><div class="mini-stat"><span>Current mode</span><b>'+(isBreak?'Break':'Focus')+'</b><span>'+(timer.preset||25)+' minute block</span></div><div class="mini-stat"><span>Sessions completed</span><b>0</b><span>Your history will appear here</span></div></div>'}
function setTimer(minutes,mode){clearInterval(timer.interval);timer.running=false;timer.seconds=minutes*60;timer.preset=minutes;timer.mode=mode;timer.custom=false;render()}
function openCustomTimer(mode){let m=document.createElement('div');m.className='modal-backdrop';m.id='custom-timer-modal';m.innerHTML='<div class="modal"><h2>Set a custom '+(mode==='break'?'break':'focus')+' timer</h2><p>Choose any duration from 1 to 180 minutes.</p><div class="field"><label>Minutes</label><input id="custom-minutes" type="number" min="1" max="180" value="'+(mode==='break'?20:45)+'"></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'custom-timer-modal\').remove()">Cancel</button><button class="primary" onclick="applyCustomTimer(\''+mode+'\')">Set timer →</button></div></div>';document.body.appendChild(m)}
function applyCustomTimer(mode){let minutes=+document.getElementById('custom-minutes').value;if(!minutes||minutes<1||minutes>180){toast('Choose between 1 and 180 minutes');return}document.getElementById('custom-timer-modal').remove();clearInterval(timer.interval);timer.running=false;timer.seconds=minutes*60;timer.preset=minutes;timer.mode=mode;timer.custom=true;render();toast('Custom '+(mode==='break'?'break':'focus')+' set for '+minutes+' minutes')}
function plannerWithShield(){return plannerFresh().replace('All courses','All classes').replace('<button class="primary" onclick="openModal()">＋ Add assignment</button>','<button class="secondary" onclick="openShieldModal()">⏱ '+(state.procrastination?.enabled?'Shield on':'Beat procrastination')+'</button><button class="primary" onclick="openModal()">＋ Add assignment</button>')}
function shiftDate(date,days){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}
function openShieldModal(){const current=state.procrastination?.days||3;let m=document.createElement('div');m.className='modal-backdrop';m.id='shield-modal';m.innerHTML='<div class="modal"><h2>Beat procrastination</h2><p>Orbit can create earlier personal deadlines while keeping the real due date visible in your data. Choose how much breathing room you want.</p><div class="field"><label>Move personal deadlines earlier by</label><select id="shield-days"><option value="1" '+(current===1?'selected':'')+'>1 day</option><option value="3" '+(current===3?'selected':'')+'>3 days</option><option value="5" '+(current===5?'selected':'')+'>5 days</option><option value="7" '+(current===7?'selected':'')+'>1 week</option></select></div><div class="reason-box" style="margin-top:15px">Example: if the real deadline is October 19, Orbit sets your personal target to October 16. October 19 stays the official due date, giving you three days to review, fix issues, and submit on time.</div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'shield-modal\').remove()">Cancel</button><button class="primary" onclick="applyShield()">'+(state.procrastination?.enabled?'Update shield':'Enable shield')+' →</button></div></div>';document.body.appendChild(m)}
function applyShield(){const days=+document.getElementById('shield-days').value;state.procrastination={enabled:true,days};state.tasks.forEach(t=>{if(!t.realDue)t.realDue=t.due;t.due=shiftDate(t.realDue,-days)});save();document.getElementById('shield-modal').remove();render();toast('Personal deadlines moved '+days+' day'+(days===1?'':'s')+' earlier')}
function disableShield(){if(!state.procrastination?.enabled)return;state.tasks.forEach(t=>{if(t.realDue){t.due=t.realDue;delete t.realDue}});state.procrastination={enabled:false,days:state.procrastination.days||3};save();render();toast('Real deadlines restored')}
function settingsFresh(){return '<div class="page-head"><div><div class="eyebrow">Workspace controls</div><h1>Settings</h1><p>Update your profile and keep your demo workspace personal.</p></div></div><div class="card"><div class="settings-nav"><button class="settings-tab active">Profile</button><button class="settings-tab" onclick="toast(\'Team features are available in the full version\')">Members</button><button class="settings-tab" onclick="toast(\'Billing is hidden in the free demo\')">Plan</button></div><div class="grid grid-2"><div><h2 style="font-family:Space Grotesk;font-size:17px;color:var(--navy)">Your profile</h2><div class="field" style="margin:15px 0"><label>Name</label><input value="'+state.user.name+'" onchange="state.user.name=this.value;save();render();toast(\'Profile updated\')"></div><div class="field"><label>What you’re working toward</label><textarea onchange="state.user.goal=this.value;save();toast(\'Goal updated\')">'+(state.user.goal||'')+'</textarea></div><button class="primary" style="margin-top:17px" onclick="toast(\'Profile saved\')">Save changes</button></div><div><h2 style="font-family:Space Grotesk;font-size:17px;color:var(--navy)">Free demo workspace</h2><p style="font-size:12px;line-height:1.6;color:var(--muted)">This demo is intentionally free and starts with a clean slate. Add your own courses and assignments to see Orbit adapt.</p><div class="reason-box">No payment details. No locked screens. Just the full product walkthrough.</div><button class="secondary" style="margin-top:15px" onclick="showTour(0)">Replay guided tour</button></div></div></div><div class="card shield-card"><div><div class="eyebrow">Optional planning support</div><h2 style="font-family:Space Grotesk;font-size:17px;color:var(--navy);margin:6px 0">Procrastination shield</h2><p style="font-size:12px;line-height:1.6;color:var(--muted);margin:0">Create earlier personal deadlines while preserving each real deadline. '+(state.procrastination?.enabled?'Currently moving tasks '+state.procrastination.days+' days earlier.':'Currently off.')+'</p></div><div class="shield-actions"><button class="secondary" onclick="openShieldModal()">'+(state.procrastination?.enabled?'Adjust buffer':'Set earlier deadlines')+'</button>'+(state.procrastination?.enabled?'<button class="secondary" onclick="disableShield()">Turn off</button>':'')+'</div></div>'}
planner = plannerWithShield;
courses = coursesFresh;
roadmap = calendarFresh;
focus = focusFlexible;
analytics = analyticsFresh;
timePlannerFresh=(()=>{const base=timePlannerFresh;return ()=>base().replace('${icons.spark}',icons.spark)})();
const baseDashboard=dashboardFresh;dashboard = ()=>baseDashboard().replace('<button class="secondary" onclick="showTour(0)">Take the guided tour</button>','');dashboardFresh=dashboard;
const baseWorkload=workload;workload=()=>state.tasks.length?baseWorkload():'<div class="empty">Your weekly workload will appear here after you add assignments.</div>';
workload=workloadEnhanced;
appShellFresh=(()=>{const base=appShellFresh;return ()=>{let html=base().replace('? Guided tour','Guided tour').replace('>Courses</span>','>Classes</span>').replace('Workspace / Courses','Workspace / Classes');if(state.tourStep===3)html=html.replace('<button class="secondary" onclick="openModal()">＋ Add task</button>','');const navStart=html.indexOf('<div class="nav-label">Workspace</div>'),navEnd=html.indexOf('<div class="side-bottom">',navStart);if(navStart>=0&&navEnd>=0){const isPlan=view==='plan'||['planner','roadmap','calendar','courses','priority','timeplanner'].includes(view);const nav='<div class="nav-label">Workspace</div><button class="nav-link '+(view==='dashboard'?'active':'')+'" onclick="go(\'dashboard\')">'+icons.grid+'<span>Overview</span></button><button class="nav-link '+(isPlan?'active':'')+'" onclick="go(\'plan\')">'+icons.calendar+'<span>Plan</span></button><button class="nav-link '+(view==='focus'?'active':'')+'" onclick="go(\'focus\')">'+icons.target+'<span>Focus mode</span></button>';html=html.slice(0,navStart)+nav+html.slice(navEnd)}if(view==='plan'||view==='roadmap'||view==='calendar'||view==='priority'||view==='timeplanner'){const start=html.indexOf('<div class="content">'),end=html.lastIndexOf('</main>'),page=view==='plan'?planHub():view==='roadmap'||view==='calendar'?calendarFresh():view==='priority'?priorityFresh():timePlannerFresh();html=html.slice(0,start)+'<div class="content">'+page+'</div>'+html.slice(end);html=html.replace('<strong>Overview</strong>','<strong>'+ (view==='plan'?'Plan':view==='roadmap'||view==='calendar'?'Calendar':view==='priority'?'Priority adjuster':'Time planner') +'</strong>')}return html}})();
courses=()=>coursesFresh().replace('Courses</h1>','Classes</h1>').replace('Courses</strong>','Classes</strong>').replace('Start with your class list, then attach assignments to the right place.','Start with your class list, then attach assignments to the right place. If you change your mind, double-click a class and use the top-right circle to select it for removal.').replace('course list','class list').replace('course</h3>','class</h3>').replace('course to build','class to build').replace('onclick="toast(\'Use Paste course list to add your first course\')"','onclick="openClassModal()"').replace('＋ Add course','＋ Add class');
settings = ()=>settingsFresh().replace('<button class="secondary" style="margin-top:15px" onclick="showTour(0)">Replay guided tour</button>','');
const baseOpenModal=openModal;openModal=()=>{baseOpenModal();const select=document.getElementById('new-priority');if(select){const option=document.createElement('option');option.value='auto';option.textContent='Auto-set from class grading';select.insertBefore(option,select.firstChild);select.value='auto';select.insertAdjacentHTML('beforebegin','<button class="auto-priority" type="button" onclick="setNewPriorityAuto()">✦ Auto-set from class grading</button>')}};
const baseAddTask=addTask;addTask=()=>{const select=document.getElementById('new-priority');if(select&&select.value==='auto')setNewPriorityAuto();baseAddTask()};
function render(){document.body.classList.toggle('tour-complete',!!state.tourComplete);const root=document.getElementById('app');if(view==='landing'){root.innerHTML=landing();return}if(view==='onboarding'||view==='login'){root.innerHTML=onboarding();return}if(!state.onboarded){view='onboarding';root.innerHTML=onboarding();return}root.innerHTML=appShellFresh();bind();if(!state.tourComplete&&!state.tourStarted&&view==='dashboard'){state.tourStarted=true;save();setTimeout(()=>showTour(0),300);}}
function landing(){return `<div class="landing"><nav class="landing-nav">${logo()}<div class="landing-nav-links"><a onclick="document.getElementById('features').scrollIntoView()">Product</a><a onclick="document.getElementById('features').scrollIntoView()">How it works</a><button class="secondary" onclick="go('onboarding')">Open free demo</button></div></nav><section class="landing-hero"><div><div class="eyebrow">A calmer command center for your semester</div><h1>Make progress feel <span>inevitable.</span></h1><p>Orbit turns a messy list of deadlines into a clear next step—so you spend less time planning and more time learning.</p><div class="landing-cta"><button class="primary" onclick="go('onboarding')">Start the free demo <span>→</span></button><button class="secondary" onclick="document.getElementById('features').scrollIntoView()">See how it works</button></div><div class="hero-note"><span>${icons.check}</span> Free interactive demo · Personalize it in under a minute</div></div><div class="preview"><div class="preview-top"><i></i><i></i><i></i></div><div class="preview-body"><div class="preview-side"><b>orbit</b><div></div><div></div><div></div><div></div></div><div class="preview-main"><h4>Your next best action</h4><div class="preview-stats"><div class="preview-stat"><b>Plan</b><small>your week</small></div><div class="preview-stat"><b>Focus</b><small>on one thing</small></div><div class="preview-stat"><b>Track</b><small>your progress</small></div></div><div class="preview-box"><b>Personalized roadmap</b><div class="fake-line"></div><div class="fake-line short"></div></div><div class="preview-box"><b>One clear next step</b><div class="fake-line"></div><div class="fake-line"></div></div></div></div></div></section><section class="landing-section" id="features"><div class="landing-section-inner"><div class="eyebrow">Less overwhelm. More momentum.</div><h2>Everything your semester needs<br>to stay in orbit.</h2><p class="section-lead">A thoughtful workspace for planning, prioritizing, and protecting the time that makes progress happen.</p><div class="feature-grid"><div class="feature-card"><div class="feature-icon">${icons.spark}</div><h3>Know what to do next</h3><p>Transparent recommendations weigh urgency, effort, difficulty, and progress to surface the right task at the right time.</p></div><div class="feature-card"><div class="feature-icon">${icons.target}</div><h3>Break big work down</h3><p>Turn intimidating projects into small, satisfying steps and watch your progress compound.</p></div><div class="feature-card"><div class="feature-icon">${icons.calendar}</div><h3>Make time for focus</h3><p>Plan a realistic week, then step into a distraction-free session built around the work in front of you.</p></div></div><div class="free-demo-banner"><div><div class="eyebrow">Try it yourself</div><h3>Free demo workspace</h3><p>Set your own name and goal, then see how Orbit helps you get moving.</p></div><button class="primary" onclick="go('onboarding')">Open the demo →</button></div></div></section></div>`}

