async function passwordDigest(value){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));return Array.from(new Uint8Array(bytes)).map(x=>x.toString(16).padStart(2,'0')).join('')}
function accountLanding(){return `<div class="landing"><nav class="landing-nav">${logo()}<div class="landing-nav-links"><a onclick="document.getElementById('features').scrollIntoView()">Product</a><a onclick="document.getElementById('features').scrollIntoView()">How it works</a><button class="secondary" onclick="showLogin()">Log in</button></div></nav><section class="landing-hero"><div><div class="eyebrow">A calmer command center for your semester</div><h1>Make progress feel <span>inevitable.</span></h1><p>Orbit turns a messy list of deadlines into a clear next step—so you spend less time planning and more time learning.</p><div class="landing-cta"><button class="primary" onclick="go('onboarding')">Create your account <span>→</span></button><button class="secondary" onclick="document.getElementById('features').scrollIntoView()">See how it works</button></div><div class="hero-note"><span>${icons.check}</span> Your workspace stays connected to your account</div></div><div class="preview"><div class="preview-top"><i></i><i></i><i></i></div><div class="preview-body"><div class="preview-side"><b>orbit</b><div></div><div></div><div></div><div></div></div><div class="preview-main"><h4>Your next best action</h4><div class="preview-stats"><div class="preview-stat"><b>Plan</b><small>your week</small></div><div class="preview-stat"><b>Focus</b><small>on one thing</small></div><div class="preview-stat"><b>Track</b><small>your progress</small></div></div><div class="preview-box"><b>Personalized calendar</b><div class="fake-line"></div><div class="fake-line short"></div></div><div class="preview-box"><b>One clear next step</b><div class="fake-line"></div><div class="fake-line"></div></div></div></div></div></section><section class="landing-section" id="features"><div class="landing-section-inner"><div class="eyebrow">Less overwhelm. More momentum.</div><h2>Everything your semester needs<br>to stay in orbit.</h2><p class="section-lead">A thoughtful workspace for planning, prioritizing, and protecting the time that makes progress happen.</p><div class="feature-grid"><div class="feature-card"><div class="feature-icon">${icons.spark}</div><h3>Know what to do next</h3><p>Transparent recommendations weigh urgency, effort, difficulty, and progress to surface the right task at the right time.</p></div><div class="feature-card"><div class="feature-icon">${icons.target}</div><h3>Break big work down</h3><p>Turn intimidating projects into small, satisfying steps and watch your progress compound.</p></div><div class="feature-card"><div class="feature-icon">${icons.calendar}</div><h3>Make time for focus</h3><p>Plan a realistic week, then step into a distraction-free session built around the work in front of you.</p></div></div></div></section></div>`}
function accountOnboarding(){return `<div class="auth-wrap"><div class="auth-card onboarding-card">${logo(false)}<div class="eyebrow">Create your Orbit account</div><h1>Make Orbit yours.</h1><p>Set up your account, then tell us what you want this workspace to help you accomplish.</p><div class="form-grid"><div class="field"><label>Username</label><input id="account-username" autocomplete="username" placeholder="Choose a username"></div><div class="field"><label>Password</label><input id="account-password" type="password" autocomplete="new-password" placeholder="At least 6 characters"></div><div class="field full"><label>What should we call you?</label><input id="onboarding-name" placeholder="Your name"></div><div class="field full"><label>What are you using Orbit for?</label><select id="onboarding-use"><option value="school">Planning my classes and assignments</option><option value="projects">Managing projects and deadlines</option><option value="habits">Building a consistent study habit</option><option value="other">Something else</option></select></div><div class="field full"><label>What would make this week feel successful?</label><textarea id="onboarding-goal" placeholder="e.g. Finish my research paper without cramming"></textarea></div></div><button class="primary" style="width:100%;padding:12px" onclick="createAccount()">Create account →</button><div class="auth-foot">Already have an account? <button class="link-button" onclick="showLogin()">Log in</button></div></div></div>`}
