async function createAccount(){const username=(document.getElementById('account-username').value||'').trim().toLowerCase(),password=document.getElementById('account-password').value||'',name=(document.getElementById('onboarding-name').value||'').trim();if(!/^[a-z0-9_.-]{3,24}$/.test(username)){toast('Choose a username with 3–24 letters or numbers');return}if(password.length<6){toast('Use a password with at least 6 characters');return}if(!name){toast('Add your name to continue');return}const accounts=accountStore();if(accounts[username]){toast('That username is already taken');return}state=JSON.parse(JSON.stringify(seed));state.user={...state.user,name,email:username,username,goal:(document.getElementById('onboarding-goal').value||'').trim(),useCase:document.getElementById('onboarding-use').value};state.org={...state.org,name:name+'’s Orbit Workspace'};state.onboarded=true;const hash=await passwordDigest(password);accounts[username]={username,passwordHash:hash,data:accountSnapshot()};localStorage.setItem('orbit_accounts_v1',JSON.stringify(accounts));activeAccount=username;localStorage.setItem('orbit_active_account',username);view='dashboard';location.hash='#/dashboard';render();toast('Your Orbit account is ready')}
