function spotlightCatchUp(){const target=[...document.querySelectorAll('button')].find(button=>button.textContent.trim()==='↺ Catch up');if(!target)return;document.querySelector('.catchup-spotlight')?.remove();const overlay=document.createElement('div');overlay.className='catchup-spotlight';overlay.innerHTML='<div class="spotlight-card"><div class="eyebrow">Recover momentum</div><h2>Catch up lives here</h2><p>Review overdue work, see points at risk, and choose the next assignment to finish.</p><div class="modal-foot"><button class="secondary" onclick="document.querySelector(\'.catchup-spotlight\')?.remove()">Got it</button><button class="primary" onclick="document.querySelector(\'.catchup-spotlight\')?.remove();openCatchUp()">Open Catch up →</button></div></div>';overlay.onclick=e=>{if(e.target===overlay)overlay.remove()};document.body.appendChild(overlay);const rect=target.getBoundingClientRect();target.classList.add('spotlight-target');target.style.position='relative';target.style.zIndex='1001';overlay.style.setProperty('--spot-x',rect.left+'px');overlay.style.setProperty('--spot-y',rect.top+'px');overlay.style.setProperty('--spot-w',rect.width+'px');overlay.style.setProperty('--spot-h',rect.height+'px')}
