function enhanceProductUI(){if(view==='login')return;document.querySelectorAll('button').forEach(button=>{if(button.textContent.trim()==='? Guided tour')button.textContent='Guided tour'});document.querySelectorAll('.calendar-legend span').forEach(el=>{if(/Orbit target/i.test(el.textContent))el.remove()});document.querySelectorAll('.catchup-item').forEach(el=>el.style.borderBottomColor='#b8c5d5');document.querySelectorAll('.page-head .secondary').forEach(button=>{if(/Session settings/i.test(button.textContent))button.remove()});const rec=document.querySelector('.recommendation .rec-button');if(rec&&state.tasks.some(t=>t.status!=='done')){rec.textContent='Get back on track →';rec.setAttribute('onclick',"go('focus')")}const coming=[...document.querySelectorAll('.card')].find(card=>card.querySelector('h2')?.textContent.trim()==='Coming up');if(coming){const title=coming.querySelector('.card-title')?.outerHTML||'<div class="card-title"><h2>Coming up</h2></div>';const priority=state.tasks.filter(t=>t.status!=='done').sort(score).slice(0,4);const rest=state.tasks.filter(t=>t.status!=='done'&&!priority.includes(t)).sort((a,b)=>a.due.localeCompare(b.due));coming.innerHTML=title+(rest.length?rest.map(t=>'<div class="deadline"><div class="date-tile"><b>'+dateLabel(t.due).day+'</b><span>'+dateLabel(t.due).mon+'</span></div><div style="flex:1"><div class="task-name">'+t.title+'</div><div class="task-sub">'+(t.type||'Homework')+' · '+t.estimate+' min</div></div><span class="pill '+t.priority.toLowerCase()+'">'+t.priority+'</span></div>').join(''):'<div class="empty">Work outside today’s priorities will appear here.</div>')}const planButton=[...document.querySelectorAll('.nav-link')].find(button=>button.textContent.trim()==='Plan');if(planButton&&!planButton.dataset.dropdown){planButton.dataset.dropdown='true';planButton.setAttribute('onclick','togglePlanMenu(event)')}if(view==='plan'){const grid=document.querySelector('.plan-hub-grid');if(grid&&!grid.querySelector('.shield-plan-card'))grid.insertAdjacentHTML('beforeend','<button class="card plan-hub-card shield-plan-card" onclick="openShieldModal()"><span class="plan-hub-icon">⏱</span><span><b>Procrastination shield</b><small>Set an earlier personal target while keeping the real deadline.</small></span><span class="plan-hub-arrow">→</span></button>')}document.querySelector('.shield-card')?.remove();document.querySelectorAll('button').forEach(button=>{if(button.textContent.trim()==='＋ Add assignment')button.textContent='＋ Add assignment/test'});const scheduleCard=document.querySelector('.calendar-time-card');if(scheduleCard){scheduleCard.querySelector('.card-title .pill')?.remove();if(!scheduleCard.querySelector('.schedule-controls'))scheduleCard.querySelector('.card-title')?.insertAdjacentHTML('beforeend','<div class="schedule-controls"><button class="secondary" onclick="shiftScheduleWeek(-1)">←</button><button class="secondary" onclick="shiftScheduleWeek(1)">→</button><button class="secondary" onclick="mirrorScheduleEveryOtherWeek()">Repeat every other week</button></div>');observeSchedule(scheduleCard)}if(view==='timeplanner'){const card=document.querySelector('.hourly-card');if(card&&!card.querySelector('.schedule-controls'))card.querySelector('.hourly-head')?.insertAdjacentHTML('beforebegin','<div class="schedule-controls"><button class="secondary" onclick="shiftScheduleWeek(-1)">← Previous week</button><button class="secondary" onclick="shiftScheduleWeek(1)">Next week →</button><button class="secondary" onclick="mirrorScheduleEveryOtherWeek()">Repeat every other week</button></div>');observeSchedule(card)}}
function togglePlanMenu(event){event?.preventDefault();document.querySelector('.plan-menu')?.remove();const button=event?.currentTarget||[...document.querySelectorAll('.nav-link')].find(el=>el.textContent.trim()==='Plan');if(!button)return;const menu=document.createElement('div');menu.className='plan-menu';menu.innerHTML='<button onclick="go(\'planner\')">Assignments</button><button onclick="go(\'calendar\')">Calendar</button><button onclick="go(\'courses\')">Classes</button><button onclick="go(\'priority\')">Priority adjuster</button>';button.parentElement.appendChild(menu)}
let scheduleWeekOffset=0;isoForWeekday=day=>{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()+(day-d.getDay())+(scheduleWeekOffset*7));return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};function shiftScheduleWeek(delta){scheduleWeekOffset+=delta;render()}function mirrorScheduleEveryOtherWeek(){const base=state.timeBlocks.filter(block=>{const d=new Date(block.date+'T12:00:00'),week=Math.floor((d-new Date(today+'T12:00:00'))/604800000);return week===0||week===-0});if(!base.length){toast('Add a weekly block first, then repeat it');return}for(let offset=14;offset<=56;offset+=14)base.forEach(block=>{const date=shiftDate(block.date,offset);if(!state.timeBlocks.some(existing=>existing.date===date&&existing.start===block.start&&existing.title===block.title))state.timeBlocks.push({...block,id:'b'+Date.now()+Math.random().toString(16).slice(2),date,day:new Date(date+'T12:00:00').getDay()})});save();render();toast('Schedule repeated every other week')}
function observeSchedule(card){if(!card||card.dataset.observed)return;card.dataset.observed='true';const observer=new IntersectionObserver(entries=>document.body.classList.toggle('weekly-schedule-focus',entries[0].isIntersecting&&entries[0].intersectionRatio>.65),{threshold:[.65]});observer.observe(card)}
const originalReason=reason;reason=t=>{const days=Math.ceil((new Date(t.due)-new Date(today))/86400000),duration=Math.round(t.estimate/60*10)/10,detail='needs about '+duration+' hours, and is '+t.progress+'% complete.';if(days<0)return 'Overdue by '+Math.abs(days)+' days, '+detail+' Starting now can help you get back on track.';if(days===0)return 'Due today, '+detail+' Starting now gives you the best chance to finish on time.';return 'Due in '+days+' day'+(days===1?'':'s')+', '+detail+' Starting now gives you enough buffer to finish without cramming.'};
function dayISOFromIndex(index){const d=new Date(today+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7)+index);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function scheduledHours(date,category){return state.timeBlocks.filter(block=>block.date===date&&(category==='studying'?block.kind==='study'||/study|exam|quiz/i.test(block.title):block.kind==='study'||/homework|hw/i.test(block.title))).reduce((sum,block)=>{const [sh,sm]=block.start.split(':').map(Number),[eh,em]=block.end.split(':').map(Number);return sum+Math.max(0,(eh*60+em-sh*60-sm)/60)},0)}
function workloadEnhancedBalanced(){const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],colors={homework:'#79a9ff',studying:'#31b982',projects:'#c29cff'},buckets=days.map((day,index)=>({homework:0,studying:0,projects:0,tasks:[],date:dayISOFromIndex(index)})),used=buckets.map(()=>0);if(!state.tasks.length)return '<div class="empty">Your weekly workload will appear here after you add assignments.</div>';const open=state.tasks.filter(t=>t.status!=='done').sort((a,b)=>a.due.localeCompare(b.due));open.forEach(task=>{let remaining=Math.max(.25,(task.estimate||0)/60),category=taskCategory(task),dueIndex=Math.max(0,Math.min(6,Math.round((new Date(task.due+'T12:00:00')-new Date(dayISOFromIndex(0)+'T12:00:00'))/86400000)));for(let i=Math.min(6,dueIndex-1);i>=0&&remaining>0;i--){const cap=scheduledHours(buckets[i].date,category)||2,space=Math.max(0,cap-used[i]),take=Math.min(space,remaining);if(take){buckets[i][category]+=take;used[i]+=take;remaining-=take}}if(remaining>0){const cap=scheduledHours(buckets[Math.min(6,dueIndex)].date,category)||1,space=Math.max(.25,cap-used[Math.min(6,dueIndex)]),take=Math.min(space,remaining);buckets[Math.min(6,dueIndex)][category]+=take;used[Math.min(6,dueIndex)]+=take;remaining-=take}if(remaining>0){const target=buckets.findIndex((_,i)=>used[i]<(scheduledHours(buckets[i].date,category)||2));if(target>=0){buckets[target][category]+=remaining;used[target]+=remaining}}buckets[Math.max(0,Math.min(6,dueIndex))].tasks.push(task)});const max=Math.max(...buckets.map(b=>b.homework+b.studying+b.projects),1);return '<div class="workload-header"><div class="workload-legend"><span><i style="background:'+colors.homework+'"></i>Homework</span><span><i style="background:'+colors.studying+'"></i>Studying</span><span><i style="background:'+colors.projects+'"></i>Projects</span></div><button class="detail-toggle '+(workloadDetailed?'active':'')+'" onclick="toggleWorkloadDetail()">'+(workloadDetailed?'Hide class details':'Show class details')+'</button></div><div class="workload-bars">'+days.map((d,i)=>{const b=buckets[i],total=b.homework+b.studying+b.projects,soft=scheduledHours(b.date,'homework')||scheduledHours(b.date,'studying');return '<div class="bar-day"><b>'+total.toFixed(1)+'h'+(soft?' / '+soft.toFixed(1)+'h soft':'')+'</b><div class="bar-stack" style="height:'+Math.max(8,total/max*112)+'px">'+['homework','studying','projects'].filter(k=>b[k]>0).map(k=>'<span style="height:'+(b[k]/max*112)+'px;background:'+colors[k]+'"></span>').join('')+'</div><span>'+d+'</span></div>'}).join('')+'</div>'+(workloadDetailed?'<div class="workload-detail">'+buckets.flatMap(b=>b.tasks).sort((a,b)=>a.due.localeCompare(b.due)).map(t=>'<div class="workload-detail-row"><span class="course-dot" style="background:'+course(t.course).color+'"></span><div><b>'+t.title+'</b><small>'+course(t.course).code+' · '+(t.type||'Homework')+' · '+t.estimate+' min</small></div><span class="pill '+t.priority.toLowerCase()+'">'+t.priority+'</span></div>').join('')+'</div>':'')}
