const orbitScore=score;score=(a,b)=>{const base=orbitScore(a,b),capacity=Math.max(1,state.timeBlocks.filter(block=>block.date===today&&(/study|homework|hw/i.test(block.title)||block.kind==='study')).reduce((sum,block)=>{const [sh,sm]=block.start.split(':').map(Number),[eh,em]=block.end.split(':').map(Number);return sum+(eh*60+em-sh*60-sm)/60},0)),todayHours=state.tasks.filter(t=>t.status!=='done'&&t.due===today).reduce((sum,t)=>sum+(t.estimate||0)/60,0);return base+(todayHours>capacity?-(todayHours-capacity)*8:0)};
