/* API-backed auth and workspace data. The JWT is kept in localStorage for now; move it to an HTTP-only cookie when the API adds cookie auth. */
async function apiRequest(path,options={}){const token=localStorage.getItem('orbit_token');const response=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{}),...(options.headers||{})}});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||'Request failed');return data}
function isoDateFromApi(value){return value?new Date(value).toISOString().slice(0,10):today}
function mapApiCourse(item){return {id:String(item._id||item.id),name:item.name,code:item.code,teacher:item.teacher||'Added by you',color:item.color||'#79a9ff'}}
function mapApiTask(item){const courseId=item.courseId?String(item.courseId._id||item.courseId):'';return {id:String(item._id||item.id),title:item.title,type:item.type||'Assignment',course:courseId,due:isoDateFromApi(item.dueAt||item.due),points:item.points||10,estimate:item.estimatedMinutes||item.estimate||60,difficulty:item.difficulty||3,priority:item.priority||'Medium',color:item.color||'#79a9ff',status:item.status||'todo',progress:item.progress||0,subtasks:item.subtasks||[],notes:item.notes||''}}
function hydrateApiWorkspace(profile,courses,tasks){state={...JSON.parse(JSON.stringify(seed)),org:{...profile.organization},user:{...state.user,name:profile.user.name,email:profile.user.email,role:profile.role||'Member'},courses:courses.map(mapApiCourse),tasks:tasks.map(mapApiTask),onboarded:true,tourComplete:state.tourComplete||false,tourStarted:state.tourStarted||false,timeBlocks:state.timeBlocks||[],grading:state.grading||{},latePolicy:state.latePolicy||{dailyPenalty:5,maxPenalty:100},procrastination:state.procrastination||{enabled:false,days:3}};localStorage.setItem('orbit_demo_v2',JSON.stringify(state))}
async function restoreApiSession(){if(!localStorage.getItem('orbit_token')){activeAccount='';view='landing';location.hash='#/';render();return}try{const profile=await apiRequest('/me'),params=new URLSearchParams(location.search);if(params.has('clear_workspace')){await apiRequest('/workspace/data',{method:'DELETE'});hydrateApiWorkspace(profile,[],[]);state.timeBlocks=[];state.grading={};state.latePolicy={dailyPenalty:5,maxPenalty:100};state.focus=0;state.tourStarted=false;state.tourComplete=false;state.procrastination={enabled:false,days:3};save();history.replaceState(null,'',location.pathname+'#/dashboard');view='dashboard';render();toast('Workspace data cleared — your login account is still active');return}const [courses,tasks]=await Promise.all([apiRequest('/courses'),apiRequest('/assignments')]);hydrateApiWorkspace(profile,courses,tasks);if(params.has('clear_calendar')){const scheduleTitles=new Set(['work','dentist appointment','homework time','study time','study','class','personal','project/paper','other']);const importedScheduleTasks=state.tasks.filter(task=>scheduleTitles.has(String(task.title||'').trim().toLowerCase())||state.courses.some(item=>item.name===task.title));for(const task of importedScheduleTasks){try{await apiRequest('/assignments/'+task.id,{method:'DELETE'})}catch{}}state.tasks=state.tasks.filter(task=>!importedScheduleTasks.includes(task));state.timeBlocks=[];save();history.replaceState(null,'',location.pathname+'#/calendar');view='calendar';render();toast('Pookie’s calendar was cleared — Academic Planner assignments and login preserved');return}view='dashboard';location.hash='#/dashboard';render()}catch(error){localStorage.removeItem('orbit_token');localStorage.removeItem('orbit_user');localStorage.removeItem('orbit_organization');activeAccount='';state=JSON.parse(JSON.stringify(seed));view='landing';location.hash='#/';render();toast(error.message||'Your session expired')}}
