function accountOnboardingForm(){return `<div class="auth-wrap"><div class="auth-card onboarding-card">${logo(false)}<div class="eyebrow">Create your Orbit account</div><h1>Make Orbit yours.</h1><p>Set up your account, then tell us what you want this workspace to help you accomplish.</p><div class="form-grid"><div class="field"><label>Email</label><input id="account-username" type="email" autocomplete="email" placeholder="you@example.com"></div><div class="field"><label>Password</label><input id="account-password" type="password" autocomplete="new-password" placeholder="At least 8 characters"></div><div class="field full"><label>What should we call you?</label><input id="onboarding-name" placeholder="Your name"></div><div class="field full"><label>What are you using Orbit for?</label><select id="onboarding-use"><option value="school">Planning my classes and assignments</option><option value="projects">Managing projects and deadlines</option><option value="habits">Building a consistent study habit</option><option value="other">Something else</option></select></div><div class="field full"><label>What would make this week feel successful?</label><textarea id="onboarding-goal" placeholder="e.g. Finish my research paper without cramming"></textarea></div></div><button class="primary" style="width:100%;padding:12px" onclick="createApiAccount()">Create account →</button><div class="auth-foot">Already have an account? <button class="link-button" onclick="showLogin()">Log in</button></div></div></div>`}
loginPage=()=>`<div class="auth-wrap"><div class="auth-card onboarding-card">${logo(false)}<div class="eyebrow">Welcome back</div><h1>Log in to Orbit.</h1><p>Pick up exactly where you left off.</p><div class="field"><label>Email</label><input id="login-username" type="email" autocomplete="email" placeholder="you@example.com"></div><div class="field"><label>Password</label><input id="login-password" type="password" autocomplete="current-password" placeholder="Your password"></div><button class="primary" style="width:100%;padding:12px" onclick="loginApiAccount()">Log in →</button><div class="auth-foot">New to Orbit? <button class="link-button" onclick="go('onboarding')">Create an account</button></div></div></div>`;
async function createApiAccount(){const name=document.getElementById('onboarding-name').value.trim(),email=document.getElementById('account-username').value.trim().toLowerCase(),password=document.getElementById('account-password').value,goal=document.getElementById('onboarding-goal').value.trim(),useCase=document.getElementById('onboarding-use').value;if(!name||!email||password.length<8){toast('Enter your name, email, and an 8-character password');return}try{const result=await apiRequest('/auth/register',{method:'POST',body:JSON.stringify({name,email,password,organizationName:name+'’s Orbit Workspace'})});localStorage.setItem('orbit_token',result.token);localStorage.setItem('orbit_user',JSON.stringify(result.user));localStorage.setItem('orbit_organization',JSON.stringify(result.organization));state=JSON.parse(JSON.stringify(seed));state.user={...state.user,name,email,goal,useCase,role:result.user.role||'Owner'};state.org={...result.organization};state.onboarded=true;save();view='dashboard';location.hash='#/dashboard';render();toast('Your Orbit account is ready')}catch(error){toast(error.message)}}
