async function refreshApiWorkspace(){if(!localStorage.getItem('orbit_token'))return;try{const [courses,tasks]=await Promise.all([apiRequest('/courses'),apiRequest('/assignments')]);state.courses=courses.map(mapApiCourse);state.tasks=tasks.map(mapApiTask);save();render()}catch(error){toast(error.message)}}
async function addApiClass(){const name=document.getElementById('class-name').value.trim(),code=document.getElementById('class-code').value.trim()||'CLASS',teacher=document.getElementById('class-teacher').value.trim()||'Added by you';if(!name){toast('Add a class name to continue');return}try{const item=await apiRequest('/courses',{method:'POST',body:JSON.stringify({name,code,teacher,color:['#79a9ff','#c29cff','#ffad72','#65d6b0'][state.courses.length%4]})});state.courses.push(mapApiCourse(item));save();document.getElementById('class-modal')?.remove();render();toast('Class added')}catch(error){toast(error.message)}}
