addClass=addApiClass;window.addClass=addApiClass;addTask=addApiTask;window.addTask=addApiTask;window.createApiAccount=createApiAccount;window.loginApiAccount=loginApiAccount;window.logoutApiAccount=logoutApiAccount;window.refreshApiWorkspace=refreshApiWorkspace;
const apiImportCourses=importCourses;importCourses=async()=>{const parsed=parseCourseList(document.getElementById('course-import-text').value);if(!parsed.length){toast('Paste at least one class to continue');return}try{for(const item of parsed){if(!state.courses.some(course=>course.code.toLowerCase()===item.code.toLowerCase())){const created=await apiRequest('/courses',{method:'POST',body:JSON.stringify({name:item.name,code:item.code,teacher:'Added by you',color:['#79a9ff','#c29cff','#ffad72','#65d6b0'][state.courses.length%4]})});state.courses.push(mapApiCourse(created))}}save();document.getElementById('course-import-modal')?.remove();render();toast(parsed.length+' class'+(parsed.length===1?'':'es')+' added')}catch(error){toast(error.message)}};window.importCourses=importCourses;
importAssignments=async()=>{const parsed=parseImportedAssignments(document.getElementById('import-text').value);if(!parsed.length){toast('Preview could not find any assignments');return}try{for(const item of parsed){let current=state.courses.find(course=>course.code.toLowerCase()===item.courseCode.toLowerCase());if(!current){const created=await apiRequest('/courses',{method:'POST',body:JSON.stringify({name:item.courseName,code:item.courseCode,teacher:'Imported from Canvas',color:['#79a9ff','#c29cff','#ffad72','#65d6b0'][state.courses.length%4]})});current=mapApiCourse(created);state.courses.push(current)}const created=await apiRequest('/assignments',{method:'POST',body:JSON.stringify({title:item.title,courseId:current.id,dueAt:new Date(item.due+'T23:59:00').toISOString(),estimatedMinutes:60,difficulty:3,priority:'Medium',type:'Assignment',notes:''})});state.tasks.push(mapApiTask({...created,courseId:current.id}))}save();document.getElementById('import-modal')?.remove();render();toast(parsed.length+' assignment'+(parsed.length===1?'':'s')+' imported')}catch(error){toast(error.message)}};window.importAssignments=importAssignments;
const localToggleTask=toggleTask;toggleTask=async id=>{const task=state.tasks.find(item=>item.id===id);if(!task)return;const nextStatus=task.status==='done'?'todo':'done';if(!localStorage.getItem('orbit_token')){localToggleTask(id);return}try{const updated=await apiRequest('/assignments/'+id,{method:'PATCH',body:JSON.stringify({status:nextStatus,progress:nextStatus==='done'?100:Math.min(task.progress||0,80)})});Object.assign(task,mapApiTask({...updated,courseId:task.course}));save();render();toast(nextStatus==='done'?'Nice work — task complete':'Task reopened')}catch(error){toast(error.message)}};window.toggleTask=toggleTask;
const apiShellRender=render;render=function(){apiShellRender();if(activeAccount||localStorage.getItem('orbit_token'))setTimeout(()=>{const topActions=document.querySelector('.top-actions');if(topActions&&!topActions.querySelector('.logout-button'))topActions.insertAdjacentHTML('beforeend','<button class="secondary logout-button" onclick="logoutApiAccount()">Log out</button>')},0)};
