scheduledHours=(date,category)=>state.timeBlocks.filter(block=>block.date===date&&((category==='studying'&&(block.kind==='study'||block.kind==='either'||/study|exam|quiz/i.test(block.title)))||(category!=='studying'&&(block.kind==='study'||block.kind==='homework'||block.kind==='either'||/homework|hw/i.test(block.title))))).reduce((sum,block)=>{const [sh,sm]=block.start.split(':').map(Number),[eh,em]=block.end.split(':').map(Number);return sum+Math.max(0,(eh*60+em-sh*60-sm)/60)},0);
