const apiImportAssignmentsWithTour=importAssignments;importAssignments=async()=>{const before=state.tasks.length;await apiImportAssignmentsWithTour();if(state.tourStarted&&!state.tourComplete&&state.tourStep===3&&state.tasks.length>before)setTimeout(()=>{closeTour();window.showTour(4)},400)};window.importAssignments=importAssignments;
function showTourWithShield(step=0){state.tourStarted=true;state.tourStep=step;save();const steps=[{title:'Welcome to your workspace',body:'This is your Overview: a quick read on what matters today, what is coming up, and the next best action.',tab:'dashboard',button:'Next →'},{title:'Add your classes first',body:'Start by pasting your class list. Orbit will separate each line into its own class so your assignments stay organized.',tab:'courses',button:'Open Classes →'},{title:'Set grading weights',body:'Tell Orbit how each class is graded so recommendations reflect what matters most.',tab:'priority',button:'Open Priority Adjuster →'},{title:'Add an assignment or exam study task',body:'Add one real assignment, exam, quiz, or study task with a deadline.',tab:'planner',button:'Open Planner →'},{title:'Set an earlier personal target',body:'After adding work, use the Procrastination Shield beside Catch up in Plan. It creates an earlier target while keeping the real deadline unchanged.',tab:'plan',button:'I see the Procrastination Shield →'},{title:'Plan the week',body:'Review your Calendar to see deadlines and protected time together.',tab:'calendar',button:'Open Calendar →'},{title:'Protect focus time',body:'Open Focus mode to turn your next task into a distraction-free work session.',tab:'focus',button:'Open Focus mode →'},{title:'Catch up without guessing',body:'Use Catch up to see overdue assignments, estimate points at risk, and decide what to work on before upcoming deadlines.',tab:'dashboard',button:'Open Catch up →'},{title:'You are ready',body:'You have seen the core loop: classes, priorities, assignments, Procrastination Shield, Calendar, focus, and Catch up.',tab:'analytics',button:'Finish guided demo'}];const current=steps[step];if(!current)return;const el=document.createElement('div');el.className='tour-backdrop';el.innerHTML='<div class="tour-card"><div class="eyebrow">Guided demo · '+(step+1)+' of '+steps.length+'</div><h2>'+current.title+'</h2><p>'+current.body+'</p><div class="tour-progress">'+steps.map((_,i)=>'<span class="'+(i<=step?'active':'')+'"></span>').join('')+'</div><div class="modal-foot"><button class="secondary" onclick="closeTour()">Skip tour</button><button class="primary" onclick="tourActionWithShield('+step+')">'+current.button+'</button></div></div>';document.body.appendChild(el);if(view!==current.tab&&!(step===1&&view==='courses')&&!(step===2&&view==='priority')&&!(step===3&&view==='planner')&&!(step===4&&view==='plan')){closeTour();go(current.tab);setTimeout(()=>showTourWithShield(step),250)}}
function tourActionWithShield(step){if(step===0){closeTour();showTourWithShield(1);return}if(step===1){closeTour();go('courses');toast('Add your classes to continue');return}if(step===2){closeTour();go('priority');toast('Set a grading weight to continue');return}if(step===3){closeTour();go('planner');toast('Add an assignment or exam study task to continue');return}if(step===4){closeTour();showTourWithShield(5);return}if(step===5){closeTour();showTourWithShield(6);return}if(step===6){closeTour();showTourWithShield(7);return}if(step===7){closeTour();openCatchUpTour();return}state.tourComplete=true;state.tourStarted=true;save();closeTour();go('dashboard');toast('Guided demo complete — your workspace is ready')}
showTour=showTourWithShield;window.showTour=showTourWithShield;window.tourActionWithShield=tourActionWithShield;completeCatchUpTour=()=>{save();closeCatchUp();toast('Catch up reviewed');setTimeout(()=>window.showTour(8),200)};window.completeCatchUpTour=completeCatchUpTour;
