const tourWithShieldStep=showTour;showTour=step=>{if(step!==4){return tourWithShieldStep(step)}state.tourStarted=true;state.tourStep=4;state.tourComplete=false;save();closeTour();go('planner');setTimeout(()=>{const target=[...document.querySelectorAll('button')].find(button=>/Beat procrastination|Shield on/.test(button.textContent.trim()));if(target)target.classList.add('tour-shield-spotlight');const el=document.createElement('div');el.className='tour-backdrop';el.innerHTML='<div class="tour-card"><div class="eyebrow">Guided demo · 5 of 9</div><h2>Set an earlier personal target</h2><p>After adding work, use the Procrastination Shield next to Add assignment/test in Planner. You can also find it beside Catch up in Plan. It creates an earlier target while keeping the real deadline unchanged.</p><div class="tour-progress">'+Array.from({length:9},(_,i)=>'<span class="'+(i<=4?'active':'')+'"></span>').join('')+'</div><div class="modal-foot"><button class="secondary" onclick="closeTour()">Skip tour</button><button class="primary" onclick="tourActionWithShield(4)">I see the Procrastination Shield →</button></div></div>';document.body.appendChild(el)},280)};window.showTour=showTour;

// Miscellaneous work can be assigned to a neutral "Other" bucket without
