const openModalWithOther=openModal;openModal=()=>{openModalWithOther();const type=document.getElementById('new-type'),courseSelect=document.getElementById('new-course');if(!type||!courseSelect)return;const syncOtherCourse=()=>{const existing=courseSelect.querySelector('option[data-other-course]');if(type.value==='Miscellaneous'){if(!existing)courseSelect.insertAdjacentHTML('beforeend','<option value="other" data-other-course>Other</option>')}else if(existing){if(courseSelect.value==='other')courseSelect.selectedIndex=0;existing.remove()}};type.addEventListener('change',syncOtherCourse);syncOtherCourse()};window.openModal=openModal;
const addTaskWithOther=addTask;addTask=async()=>{const courseSelect=document.getElementById('new-course');if(courseSelect?.value==='other'){try{let other=state.courses.find(course=>course.code==='OTHER');if(!other&&localStorage.getItem('orbit_token')){other=mapApiCourse(await apiRequest('/courses',{method:'POST',body:JSON.stringify({name:'Other',code:'OTHER',teacher:'General',color:'#aeb9c8'})}));state.courses.push(other)}else if(!other){other={id:'other',name:'Other',code:'OTHER',teacher:'General',color:'#aeb9c8'};state.courses.push(other)}courseSelect.value=other.id}catch(error){toast(error.message);return}}await addTaskWithOther()};window.addTask=addTask;

