let selectedClassIds=new Set();
function refreshBulkClassUI(){const cards=[...document.querySelectorAll('.course-card')],active=selectedClassIds.size>0;cards.forEach((card,index)=>{const item=state.courses[index];if(!item)return;card.classList.toggle('class-selected',selectedClassIds.has(item.id));let toggle=card.querySelector('.class-select-toggle');if(active&&!toggle){card.insertAdjacentHTML('afterbegin','<button class="class-select-toggle" aria-label="Select class"></button>');toggle=card.querySelector('.class-select-toggle')}if(toggle){toggle.classList.toggle('checked',selectedClassIds.has(item.id));toggle.onclick=e=>{e.stopPropagation();toggleClassSelection(item.id)}}card.ondblclick=()=>{if(!selectedClassIds.size){selectedClassIds.add(item.id);refreshBulkClassUI()}else toggleClassSelection(item.id)}});let bar=document.getElementById('bulk-class-actions');if(!active){bar?.remove();return}if(!bar){bar=document.createElement('div');bar.id='bulk-class-actions';document.body.appendChild(bar)}bar.innerHTML='<span>'+selectedClassIds.size+' class'+(selectedClassIds.size===1?'':'es')+' selected</span><button class="secondary" onclick="exitClassSelection()">Cancel</button><button class="bulk-delete-button" onclick="openBulkDeleteClassesModal()">Delete selected</button>'}
