function openBulkDeleteClassesModal(){if(!selectedClassIds.size)return;document.getElementById('bulk-delete-class-modal')?.remove();const names=state.courses.filter(course=>selectedClassIds.has(course.id)).map(course=>course.name),modal=document.createElement('div');modal.className='modal-backdrop';modal.id='bulk-delete-class-modal';modal.setAttribute('onclick','if(event.target===event.currentTarget)this.remove()');modal.innerHTML='<div class="modal delete-confirm-modal"><button class="modal-close" aria-label="Close bulk delete confirmation" onclick="document.getElementById(\'bulk-delete-class-modal\')?.remove()">×</button><div class="eyebrow">Remove selected classes</div><h2>Delete '+names.length+' class'+(names.length===1?'':'es')+'?</h2><p>'+names.map(name=>name.replace(/</g,'&lt;').replace(/>/g,'&gt;')).join(', ')+' will be deleted, along with their connected assignments. This action cannot be undone.</p><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'bulk-delete-class-modal\')?.remove()">Cancel</button><button class="bulk-delete-button" onclick="confirmBulkDeleteClasses()">Delete selected</button></div></div>';document.body.appendChild(modal)}
async function confirmBulkDeleteClasses(){const ids=[...selectedClassIds],items=state.courses.filter(course=>ids.includes(course.id));try{if(localStorage.getItem('orbit_token'))for(const id of ids)await apiRequest('/courses/'+id,{method:'DELETE'});state.courses=state.courses.filter(course=>!ids.includes(course.id));state.tasks=state.tasks.filter(task=>!ids.includes(task.course));selectedClassIds.clear();document.getElementById('bulk-delete-class-modal')?.remove();save();render();toast(items.length+' class'+(items.length===1?'':'es')+' deleted')}catch(error){toast(error.message)}}
