function showErrorModal(message,title='Something went wrong'){document.getElementById('error-modal')?.remove();const modal=document.createElement('div');modal.className='modal-backdrop';modal.id='error-modal';modal.setAttribute('onclick','if(event.target===event.currentTarget)this.remove()');const safe=String(message||'Please try again.').replace(/</g,'&lt;').replace(/>/g,'&gt;');modal.innerHTML='<div class="modal error-modal"><button class="modal-close" aria-label="Close error" onclick="document.getElementById(\'error-modal\')?.remove()">×</button><div class="eyebrow">Orbit alert</div><h2>'+title+'</h2><p>'+safe+'</p><div class="modal-foot"><button class="primary" onclick="document.getElementById(\'error-modal\')?.remove()">Got it</button></div></div>';document.body.appendChild(modal)}window.showErrorModal=showErrorModal;
