function updateTimerSurface(){const timerEl=document.querySelector('.timer');if(timerEl)timerEl.textContent=Math.floor(Math.max(0,timer.seconds)/60).toString().padStart(2,'0')+':'+(Math.max(0,timer.seconds)%60).toString().padStart(2,'0');const label=document.querySelector('.timer-label');if(label)label.textContent=timer.mode==='break'?(timer.running?'Break in progress':'Break time · recharge before the next block'):timer.running?'Deep work in progress':'Ready when you are';const control=document.querySelector('.timer-controls button:first-child');if(control)control.textContent=timer.running?'Pause':timer.mode==='break'?'Start break':'Start focus'}
function toggleTimerStable(){if(timer.running){clearInterval(timer.interval);timer.running=false;updateTimerSurface();return}if(timer.seconds<=0)timer.seconds=Math.max(1,(timer.preset||25)*60);timer.running=true;updateTimerSurface();timer.interval=setInterval(()=>{timer.seconds=Math.max(0,timer.seconds-1);updateTimerSurface();if(timer.seconds===0){clearInterval(timer.interval);timer.running=false;playTimerChime();toast(timer.mode==='break'?'Break complete — ready to focus?':'Focus session complete — great work');updateTimerSurface()}},1000)}toggleTimer=toggleTimerStable;window.toggleTimer=toggleTimer;

function addFocusTaskBox(){if(view!=='focus'||document.querySelector('.focus-task-box'))return;const host=document.querySelector('.content');const grid=host?.querySelector('.grid');if(!grid)return;const box=document.createElement('div');box.className='card focus-task-box';box.innerHTML='<div class="eyebrow">Session intention</div><h2>What are you working on?</h2><input id="focus-task-label" placeholder="e.g. Draft my research paper or study for CS 4230" value="'+String(state.focusTaskLabel||'').replace(/"/g,'&quot;')+'"><small>This keeps your focus session connected to a real assignment, study block, or project.</small>';box.querySelector('input').addEventListener('change',event=>{state.focusTaskLabel=event.target.value.trim();save()});host.insertBefore(box,grid)}

