function openEditClassModal(id){const item=state.courses.find(course=>course.id===id);if(!item)return;document.getElementById('edit-class-modal')?.remove();const modal=document.createElement('div');modal.className='modal-backdrop';modal.id='edit-class-modal';modal.setAttribute('onclick','if(event.target===event.currentTarget)this.remove()');modal.innerHTML='<div class="modal"><button class="modal-close" aria-label="Close edit class" onclick="document.getElementById(\'edit-class-modal\')?.remove()">×</button><div class="eyebrow">Class details</div><h2>Edit class</h2><div class="field"><label>Class name</label><input id="edit-class-name" value="'+item.name.replace(/"/g,'&quot;')+'"></div><div class="field" style="margin-top:12px"><label>Class code</label><input id="edit-class-code" value="'+item.code.replace(/"/g,'&quot;')+'"></div><div class="field" style="margin-top:12px"><label>Instructor</label><input id="edit-class-teacher" value="'+String(item.teacher||'').replace(/"/g,'&quot;')+'"></div><div class="modal-foot"><button class="secondary" onclick="document.getElementById(\'edit-class-modal\')?.remove()">Cancel</button><button class="primary" onclick="saveClassEdits(\''+id+'\')">Save changes</button></div></div>';document.body.appendChild(modal)}
async function saveClassEdits(id){const item=state.courses.find(course=>course.id===id);if(!item)return;const update={name:document.getElementById('edit-class-name').value.trim(),code:document.getElementById('edit-class-code').value.trim(),teacher:document.getElementById('edit-class-teacher').value.trim()};if(!update.name||!update.code){showErrorModal('Class name and class code are required.','Class details incomplete');return}try{const saved=localStorage.getItem('orbit_token')?mapApiCourse(await apiRequest('/courses/'+id,{method:'PATCH',body:JSON.stringify(update)})):null;Object.assign(item,saved||update);save();document.getElementById('edit-class-modal')?.remove();render();toast('Class details updated')}catch(error){showErrorModal(error.message,'Could not update class')}}window.openEditClassModal=openEditClassModal;window.saveClassEdits=saveClassEdits;
