const savePriorityWithValidation=savePriorityAdjustments;savePriorityAdjustments=()=>{const invalid=state.courses.map(c=>({c,total:Object.values(classWeights(c.id)).reduce((sum,value)=>sum+Number(value||0),0)})).filter(x=>x.total!==100);if(invalid.length){showErrorModal(invalid.map(x=>x.c.name+' is at '+x.total+'%').join('\n')+'\n\nEach class must total exactly 100% before saving.','Grading weights must equal 100%');return}savePriorityWithValidation()};window.savePriorityAdjustments=savePriorityAdjustments;

const planRoutesForMenu=['planner','roadmap','calendar','courses','priority','timeplanner'];const renderWithOpenPlanMenu=render;render=()=>{renderWithOpenPlanMenu();if(planRoutesForMenu.includes(view))setTimeout(()=>{if(!document.querySelector('.plan-menu')){const button=[...document.querySelectorAll('.nav-link')].find(el=>el.textContent.trim()==='Plan');if(button)togglePlanMenu({preventDefault(){},currentTarget:button})}},0)};window.render=render;
const loginPageWithRememberedUser=loginPage;loginPage=()=>{const remembered=String(localStorage.getItem('orbit_last_username')||'').replace(/"/g,'&quot;');return loginPageWithRememberedUser().replace('id="login-username" type="text"','id="login-username" type="text" value="'+remembered+'"')};window.loginPage=loginPage;
parseCourseList=text=>{const source=String(text||'').replace(/\r\n?/g,'\n').replace(/[•·]/g,'-');let lines=source.split('\n').flatMap(line=>line.split(/\s+(?=[A-Z]{2,6}\s*\d{3,5}(?:\.\d+)?(?:\s|\())/i)).map(line=>line.replace(/^\s*[-*]+\s*/,'').replace(/^\[([^\]]+)\]\([^)]+\)\s*/,'').replace(/\s+/g,' ').trim()).filter(Boolean);return lines.map(line=>{const match=line.match(/^([A-Z]{2,6}\s*\d{3,5}(?:\.\d+)?)/i),code=match?match[1].replace(/\s+/g,' ').trim():'CLASS',name=match?line.slice(match[1].length).replace(/^\s*(?:\([^)]*\))?\s*/,'').trim()||line:line;return {code,name}}).filter(item=>item.name).filter((item,index,items)=>items.findIndex(other=>other.code.toLowerCase()===item.code.toLowerCase()&&other.name.toLowerCase()===item.name.toLowerCase())===index)};
function showExploreTourStep(step,tab,title,body,nextLabel){state.tourStarted=true;state.tourStep=step;state.tourComplete=false;save();closeTour();go(tab);setTimeout(()=>{const el=document.createElement('div');el.className='tour-explore-backdrop';el.innerHTML='<div class="tour-card tour-explore-card"><div class="eyebrow">Guided demo · '+(step+1)+' of 9</div><h2>'+title+'</h2><p>'+body+'</p><div class="tour-progress">'+Array.from({length:9},(_,i)=>'<span class="'+(i<=step?'active':'')+'"></span>').join('')+'</div><div class="modal-foot"><button class="secondary" onclick="closeTour()">Skip tour</button><button class="primary" onclick="tourActionWithShield('+step+')">'+nextLabel+'</button></div></div>';document.body.appendChild(el)},280)}
const tourBeforeExploreSteps=showTour;showTour=step=>{if(step===5)return showExploreTourStep(5,'calendar','Explore your Calendar','Review deadlines, study sessions, and your schedule. You can click around and explore the page before continuing.','I’m done exploring →');if(step===6)return showExploreTourStep(6,'focus','Explore Focus mode','Try the timer controls, choose a focus or break length, and add what you are working on. Explore the page before continuing.','I’m done exploring →');return tourBeforeExploreSteps(step)};window.showTour=showTour;
const tourBeforeExploreActions=tourActionWithShield;tourActionWithShield=step=>{if(step===5){closeTour();showTour(6);return}if(step===6){closeTour();showTour(7);return}return tourBeforeExploreActions(step)};window.tourActionWithShield=tourActionWithShield;

