/* Planner and focus follow-up pass. */
let pastAssignmentsOpen=false,selectedPastAssignments=new Set();
const priorityRank={High:0,Medium:1,Low:2};
function sortedPlannerTasks(includeCompleted=false){return state.tasks.filter(task=>includeCompleted?task.status==='done':task.status!=='done').sort((a,b)=>(priorityRank[a.priority]??1)-(priorityRank[b.priority]??1)||String(a.due||'').localeCompare(String(b.due||''))||a.title.localeCompare(b.title))}
function plannerAssignmentRow(task,isPast=false){const checked=selectedPastAssignments.has(task.id);return '<tr data-task data-course="'+task.course+'" data-status="'+task.status+'" data-priority="'+task.priority+'" data-search="'+task.title.toLowerCase()+'" class="'+(isPast&&checked?'past-selected':'')+'"><td><div class="task-cell"><button class="check '+(isPast&&checked?'done':'')+'" aria-label="'+(isPast?'Select '+task.title:'Complete '+task.title)+'" onclick="'+(isPast?'togglePastAssignment(\''+task.id+'\')':'toggleTask(\''+task.id+'\')')+'">'+(isPast&&checked?icons.check:(!isPast&&task.status==='done'?icons.check:''))+'</button><span style="font-weight:600">'+task.title+'</span></div></td><td><span class="course-chip"><span class="course-dot" style="background:'+course(task.course).color+'"></span>'+course(task.course).code+'</span></td><td>'+dateLabel(task.due).full+'</td><td>'+task.estimate+' min</td><td><div class="progress mini-progress"><span style="width:'+Math.max(0,Math.min(100,Number(task.progress)||0))+'%"></span></div><small class="progress-label">'+(Number(task.progress)||0)+'%</small></td><td><span class="pill '+String(task.priority||'Medium').toLowerCase()+'">'+(task.priority||'Medium')+'</span></td><td><button class="icon-btn" aria-label="Start '+task.title+'" onclick="startTask(\''+task.id+'\')">'+icons.target+'</button></td></tr>'}
function plannerBoard(){const tasks=sortedPlannerTasks(pastAssignmentsOpen),rows=tasks.map(task=>plannerAssignmentRow(task,pastAssignmentsOpen)).join('');return '<div class="page-head"><div><div class="eyebrow">Your workload, made workable</div><h1>Assignment planner</h1><p>Every deadline in one calm, prioritized view.</p></div><div class="page-actions">'+(state.procrastination?.enabled?'<button class="secondary" onclick="disableShield()">Remove shield</button>':'<button class="secondary" onclick="openShieldModal()">⏱ Beat procrastination</button>')+'<button class="secondary" onclick="openImportModal()">↥ Paste from Canvas</button><button class="secondary past-toggle '+(pastAssignmentsOpen?'active':'')+'" onclick="togglePastAssignments()">'+(pastAssignmentsOpen?'← Current assignments':'Past assignments ('+state.tasks.filter(task=>task.status==='done').length+')')+'</button><button class="primary" onclick="openModal()">＋ Add assignment/test</button></div></div><div class="card"><div class="toolbar"><div class="search">'+icons.search+'<input id="task-search" placeholder="Search assignments..." oninput="filterTasks()"></div><div class="filters"><select id="course-filter" onchange="filterTasks()"><option value="all">All classes</option>'+state.courses.map(c=>'<option value="'+c.id+'">'+c.code+'</option>').join('')+'</select><select id="priority-filter" onchange="filterTasks()"><option value="all">All priority</option><option>High</option><option>Medium</option><option>Low</option></select></div></div><div id="task-table"><table class="table"><thead><tr><th style="width:34%">Assignment</th><th>Class</th><th>Due date</th><th>Time</th><th>Progress</th><th>Priority</th><th></th></tr></thead><tbody>'+(rows||'<tr><td colspan="7"><div class="empty">'+(pastAssignmentsOpen?'No completed assignments yet.':'No current assignments yet. Add one manually or paste your Canvas assignment list.')+'</div></td></tr>')+'</tbody></table>'+(pastAssignmentsOpen&&selectedPastAssignments.size?'<div class="past-actions"><span>'+selectedPastAssignments.size+' selected</span><button class="primary" onclick="restorePastAssignments()">✓ Bring back to current list</button></div>':'')+'</div></div>'}
function togglePastAssignments(){pastAssignmentsOpen=!pastAssignmentsOpen;selectedPastAssignments.clear();render()}
function togglePastAssignment(id){if(selectedPastAssignments.has(id))selectedPastAssignments.delete(id);else selectedPastAssignments.add(id);render()}
async function restorePastAssignments(){const ids=[...selectedPastAssignments];for(const id of ids){const task=state.tasks.find(item=>item.id===id);if(!task)continue;const courseId=task.course;task.status='todo';task.progress=0;if(localStorage.getItem('orbit_token')){try{const updated=await apiRequest('/assignments/'+id,{method:'PATCH',body:JSON.stringify({status:'todo',progress:0})});Object.assign(task,mapApiTask({...updated,courseId}))}catch(error){showErrorModal(error.message,'Could not restore assignment');return}}}selectedPastAssignments.clear();pastAssignmentsOpen=false;save();render();toast(ids.length+' assignment'+(ids.length===1?'':'s')+' brought back')}
planner=plannerBoard;window.togglePastAssignments=togglePastAssignments;window.togglePastAssignment=togglePastAssignment;window.restorePastAssignments=restorePastAssignments;window.toggleStudyGroup=toggleStudyGroup;window.filterTasks=filterAcademicPlanner;
