parseImportedAssignments=(text)=>{const source=String(text||'').replace(/\r\n?/g,'\n');const pattern=/\[\*\*(.+?)\*\*\]\((https?:\/\/[^)]+)\)\s*([^|\n]+?)\|\s*\[Go to course\]\([^)]+\)\s*(\d+)\s*pts\s*\*\*(\d{1,2}\/\d{1,2}\/\d{4})\s+(\d{1,2}:\d{2}\s*[AP]M)\*\*/gi;const parsed=[];let match;while((match=pattern.exec(source))){const courseText=match[3].trim(),codeMatch=courseText.match(/^(.+?)(?:\s*\([^)]*\))?\s+([^()]+)$/),courseCode=(codeMatch?codeMatch[1]:courseText).trim(),courseName=(codeMatch?codeMatch[2]:courseText).trim(),[month,day,year]=match[5].split('/');parsed.push({title:match[1].trim(),url:match[2],courseCode,courseName,due:year+'-'+month.padStart(2,'0')+'-'+day.padStart(2,'0'),displayDue:match[5]+' '+match[6],points:Number(match[4])})}return parsed};
