scheduledHours=(date,category)=>state.timeBlocks.filter(block=>{if(block.date!==date)return false;const title=(block.title||'').toLowerCase(),kind=block.kind||'';return category==='studying'?(kind==='study'||kind==='either'||/study|exam|quiz|test/.test(title)):(kind==='homework'||kind==='either'||/homework|hw|project/.test(title))}).reduce((sum,block)=>{const [sh,sm]=String(block.start).split(':').map(Number),[eh,em]=String(block.end).split(':').map(Number);return sum+Math.max(0,(eh*60+em-sh*60-sm)/60)},0);
function capacityAwareTasksForDate(date){const limits={homework:scheduledHours(date,'homework'),studying:scheduledHours(date,'studying')},used={homework:0,studying:0},selected=[];state.tasks.filter(task=>task.status!=='done'&&task.due>=date).sort((a,b)=>(priorityRank[a.priority]??1)-(priorityRank[b.priority]??1)||String(a.due).localeCompare(String(b.due))).forEach(task=>{const group=planningGroup(task),hours=Math.max(.25,Number(task.estimate||60)/60);if(limits[group]>0&&used[group]+hours<=limits[group]+.001){selected.push(task);used[group]+=hours}});return {selected,limits,used}}
function workloadCapacityAware(){const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],colors={homework:'#79a9ff',studying:'#31b982'},buckets=days.map((day,index)=>({date:dayISOFromIndex(index),homework:0,studying:0,tasks:[]}));if(!state.tasks.some(task=>task.status!=='done'))return '<div class="empty">Your weekly workload will appear here after you add assignments and time blocks.</div>';const open=state.tasks.filter(task=>task.status!=='done').sort((a,b)=>(priorityRank[a.priority]??1)-(priorityRank[b.priority]??1)||String(a.due).localeCompare(String(b.due)));open.forEach(task=>{let remaining=Math.max(.25,Number(task.estimate||60)/60),group=planningGroup(task),dueIndex=Math.max(0,Math.min(6,buckets.findIndex(bucket=>bucket.date>=task.due)));if(dueIndex<0)dueIndex=6;for(let index=0;index<=dueIndex&&remaining>0;index++){const capacity=scheduledHours(buckets[index].date,group),used=buckets[index][group],take=Math.min(remaining,Math.max(0,capacity-used));if(take>0){buckets[index][group]+=take;remaining-=take}}if(remaining<Number(task.estimate||60)/60)buckets[dueIndex].tasks.push(task)});const max=Math.max(...buckets.map(bucket=>bucket.homework+bucket.studying),1);return '<div class="workload-header"><div class="workload-legend"><span><i style="background:'+colors.homework+'"></i>Homework + projects</span><span><i style="background:'+colors.studying+'"></i>Study + tests + quizzes</span></div><button class="detail-toggle '+(workloadDetailed?'active':'')+'" onclick="toggleWorkloadDetail()">'+(workloadDetailed?'Hide class details':'Show class details')+'</button></div><div class="workload-bars">'+buckets.map((bucket,index)=>{const total=bucket.homework+bucket.studying,homeCap=scheduledHours(bucket.date,'homework'),studyCap=scheduledHours(bucket.date,'studying');return '<div class="bar-day"><b>'+total.toFixed(1)+'h</b><div class="bar-stack" style="height:'+Math.max(8,total/max*112)+'px">'+(bucket.homework?'<span style="height:'+(bucket.homework/max*112)+'px;background:'+colors.homework+'"></span>':'')+(bucket.studying?'<span style="height:'+(bucket.studying/max*112)+'px;background:'+colors.studying+'"></span>':'')+'</div><span>'+days[index]+'</span><small class="workload-capacity">'+(homeCap+studyCap).toFixed(1)+'h available</small></div>'}).join('')+'</div>'+(workloadDetailed?'<div class="workload-detail">'+buckets.flatMap(bucket=>bucket.tasks).map(task=>'<div class="workload-detail-row"><span class="course-dot" style="background:'+course(task.course).color+'"></span><div><b>'+task.title+'</b><small>'+course(task.course).code+' · '+(task.type||'Homework')+' · '+task.estimate+' min</small></div><span class="pill '+String(task.priority||'Medium').toLowerCase()+'">'+(task.priority||'Medium')+'</span></div>').join('')+'</div>':'')}
