// Keep Today’s priorities useful even when a task is larger than one day’s
// soft capacity. The workload chart can split the hours across several days,
// but the old priority filter discarded any task that could not fit whole in
// the remaining hours. That made urgent work disappear from the to-do list.
function capacityAwareTasksForDateWithOverflow(date){
  const limits={homework:scheduledHours(date,'homework'),studying:scheduledHours(date,'studying')},
    used={homework:0,studying:0},selected=[],overflow=[];
  const sortTasks=(a,b)=>{
    const aUrgent=a.due<=date?0:1,bUrgent=b.due<=date?0:1;
    return aUrgent-bUrgent||(priorityRank[a.priority]??1)-(priorityRank[b.priority]??1)||String(a.due).localeCompare(String(b.due));
  };
  const open=state.tasks.filter(task=>task.status!=='done').sort(sortTasks);
  open.forEach(task=>{
    const group=planningGroup(task),hours=Math.max(.25,Number(task.estimate||60)/60);
    if(limits[group]>0&&used[group]+hours<=limits[group]+.001){
      selected.push(task);used[group]+=hours;
    }else overflow.push(task);
  });
  const mustShow=[];
  // Anything already due is always visible, even when the schedule is full.
  overflow.filter(task=>task.due<=date).forEach(task=>mustShow.push(task));
  // If a category has no task that fits, keep its highest-priority task visible
  // so a large assignment is never silently dropped from Today’s priorities.
  ['homework','studying'].forEach(group=>{
    if(!selected.some(task=>planningGroup(task)===group)){
      const candidate=overflow.find(task=>planningGroup(task)===group);
      if(candidate&&!mustShow.includes(candidate))mustShow.push(candidate);
    }
  });
  const combined=[...selected,...mustShow].sort(sortTasks);
  return {selected:combined,limits,used,overflow};
}
capacityAwareTasksForDate=capacityAwareTasksForDateWithOverflow;
