async function createStudyPlanForAssessment(assessment){if(assessment.studyPlanCreated||!/quiz|test|exam|midterm|final/i.test((assessment.type||'')+' '+assessment.title)||assessment.due<=today)return;const dates=studyDateRange(today,assessment.due).filter(date=>scheduledHours(date,'studying')>0);if(!dates.length)return;let remaining=Math.max(1,Math.ceil(Number(assessment.estimate||60)/60)),created=[];for(const date of dates){if(remaining<=0)break;const minutes=Math.min(Math.round(scheduledHours(date,'studying')*60),remaining*60);if(minutes<=0)continue;const title='Study for '+assessment.title,localTask={id:'t'+Date.now()+Math.random().toString(16).slice(2),title,type:'Study',course:assessment.course,due:date,estimate:minutes,difficulty:2,priority:'High',status:'todo',progress:0,subtasks:1,points:0,studyFor:assessment.id};if(localStorage.getItem('orbit_token')){try{const saved=await apiRequest('/assignments',{method:'POST',body:JSON.stringify({title,type:'Study',courseId:assessment.course,dueAt:new Date(date+'T23:59:00').toISOString(),estimatedMinutes:minutes,difficulty:2,priority:'High',notes:'Suggested study session for '+assessment.title})});created.push(mapApiTask(saved))}catch(error){showErrorModal(error.message,'Could not create study plan');return}}else created.push(localTask);remaining-=Math.ceil(minutes/60)}if(created.length){state.tasks.push(...created);assessment.studyPlanCreated=true;save();toast(created.length+' study session'+(created.length===1?'':'s')+' planned before '+assessment.title);render()}}
