// Keep grouped exam/quiz study sessions aligned with the recurring weekly schedule.
function studyBlockMatches(block){const title=String(block.title||'').toLowerCase(),kind=String(block.kind||'').toLowerCase();return kind==='study'||kind==='either'||/study|exam|quiz|test/.test(title)}
function studyBlockDuration(block){const [sh,sm]=String(block.start||'').split(':').map(Number),[eh,em]=String(block.end||'').split(':').map(Number);return Number.isFinite(sh)&&Number.isFinite(eh)?Math.max(0,(eh*60+(em||0)-sh*60-(sm||0))/60):0}
