let catchUpGlowTimer=null;const showTourWithPersistentCatchUpGlow=showTour;showTour=step=>{if(step!==7)return showTourWithPersistentCatchUpGlow(step);showTourWithPersistentCatchUpGlow(step);clearInterval(catchUpGlowTimer);catchUpGlowTimer=setInterval(()=>{if(!document.querySelector('.tour-backdrop')){clearInterval(catchUpGlowTimer);catchUpGlowTimer=null;return}const target=[...document.querySelectorAll('.plan-menu button')].find(button=>button.textContent.trim()==='Catch Up');if(target){target.classList.add('spotlight-target','tour-catchup-sidebar-spotlight');target.style.position='relative';target.style.zIndex='1001'}},80)};window.showTour=showTour;
