// Catch Up is spotlighted only on the dedicated Catch Up tour step (8 of 9).
// Clear any stale spotlight before rendering every other step.
const showTourWithoutEarlyCatchUpGlow=showTour;showTour=step=>{if(step!==7){clearInterval(catchUpGlowTimer);document.querySelectorAll('.tour-catchup-sidebar-spotlight,.spotlight-target').forEach(el=>{el.classList.remove('tour-catchup-sidebar-spotlight','spotlight-target');el.style.position='';el.style.zIndex=''})}return showTourWithoutEarlyCatchUpGlow(step)};window.showTour=showTour;

// Keep the guided flow in control while still allowing users to explore the
// current page. Sidebar navigation is restored as soon as the tour closes.
function setGuidedTourNavLock(locked){const sidebar=document.querySelector('.sidebar');if(sidebar)sidebar.style.pointerEvents=locked?'none':'';document.body.classList.toggle('guided-tour-nav-locked',locked)}
const showTourWithNavLock=showTour;showTour=step=>{const result=showTourWithNavLock(step);setTimeout(()=>setGuidedTourNavLock(true),0);return result};window.showTour=showTour;
const closeTourWithNavUnlock=closeTour;closeTour=()=>{closeTourWithNavUnlock();setGuidedTourNavLock(false)};window.closeTour=closeTour;
